    def test_offset6_link_hidden_when_vault_state_incomplete(self):
        # Checker-improvement (2026-11-22): a half-filled vault state
        # (assets without shares, or the reverse) makes the donation
        # check refuse before any parameter matters — verified live,
        # the same refusal comes back at offset 6. The "see whether
        # offset 6 fixes it" link therefore points at a fix that
        # cannot fix it, so both the sentence and the button stay
        # hidden until the state is complete or the failure is a
        # measured one. The audit CTA and the slippage-bound paragraph
        # stay: a human review is still the next step, and the table's
        # Note column already tells the visitor what is missing.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        half = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                    victim_deposit=100_000_000_000,
                    vault_assets=1_000_000_000, vault_supply=0),
            vic=100_000_000_000, off=0, mn=0, fee=0,
            vassets=1_000_000_000, vshares=0)
        # Visual verdict 2026-11-23 01:07: the banner heads the
        # results ("Full results — 2 of 6 failed ...") instead of
        # restating the verdict; the verdict words live in the
        # strip only.
        self.assertIn("Full results &mdash; 2 of 6 failed: Donation inflation, "
                      "Minimum viable deposit", half)
        self.assertNotIn("Result: SOME FAILED", half)
        self.assertIn("incomplete vault state", half)
        self.assertNotIn("Run the same checks with offset 6</a>", half)
        self.assertNotIn("see whether a decimals offset fixes it", half)
        self.assertIn("Get the vault micro-audit</a>", half)
        self.assertIn("/guides/erc4626-slippage-bounds/", half)
        # Mirror image: shares without assets refuses the same way.
        half2 = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                    victim_deposit=100_000_000_000,
                    vault_assets=0, vault_supply=1_000_000_000),
            vic=100_000_000_000, off=0, mn=0, fee=0,
            vassets=0, vshares=1_000_000)
        self.assertNotIn("Run the same checks with offset 6</a>", half2)
        # Control: a giant minimum deposit also fails at offset 0, but
        # its rows carry a different error ("below minimum deposit"),
        # so the offset-6 link stays — only the incomplete-state
        # refusal hides it.
        giant = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=10**15,
                          perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=10**15, fee=0)
        self.assertIn("Run the same checks with offset 6</a>", giant)
        self.assertIn("see whether a decimals offset fixes it", giant)
        # Worker JS renderer: the same guard, in both gates.
        js = build.checker_results_html_js()
        fn = js[js.index("function resultsHTML"):]
        self.assertIn("incomplete vault state", fn)
        self.assertEqual(fn.count("&&!donIncomplete)"), 2)

    def test_pass_notice_is_green(self):
        # Visual verdict #148 item 3 (2026-11-22): on a passing run
        # the amber "What to do next" box sat directly under the green
        # result banner and read as a warning against a pass. The pass
        # notice now reuses the pass banner's palette; the fail notice
        # keeps the amber warning box. Worker rendering is verified by
        # the /tmp pass-notice node harness.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        passed = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertIn("<div class='notice notice-pass'>", passed)
        # Visual verdict 17:07 follow-up (2026-11-22): the notice no
        # longer restates the verdict — "This preset passes the model"
        # was the third statement of it (strip + banner already say
        # ALL PASS). The notice opens with the floor sentence now.
        self.assertIn("Six checks are the floor, not the ceiling", passed)
        self.assertNotIn("This preset passes the model", passed)
        self.assertNotIn("<div class='notice'><h3>What to do next</h3>",
                         passed)
        failed = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("<div class='notice'><h3>What to do next</h3>", failed)
        self.assertNotIn("notice-pass", failed)
        # The green box reuses the pass banner's exact palette.
        self.assertIn(".notice-pass{background:#e6f4ea;border-color:#bbe0c6}",
                      build.CSS)
        # Worker JS renderer: the pass branch carries the class, the
        # fail branch keeps the plain amber box.
        js = build.checker_results_html_js()
        fn = js[js.index("function resultsHTML"):]
        self.assertIn(
            "<div class='notice notice-pass'><h3>What to do next</h3>"
            "<p>Six checks are the floor", fn)
        self.assertIn(
            "<div class='notice'><h3>What to do next</h3><p>This is a model of the math",
            fn)
        # Neither renderer restates the verdict in the notice (see
        # test_result_notice_does_not_restate_verdict).
        self.assertNotIn("A check failed.", fn)
        self.assertNotIn("This preset passes the model", fn)

    def test_result_notice_does_not_restate_verdict(self):
        # Visual verdict 17:07 follow-up (2026-11-22,
        # checker-improvement): on the live checker page the verdict
        # was stated three times — strip ("Result: SOME FAILED."),
        # banner ("Result: SOME FAILED — 1 of 6 failed ..."), and the
        # "What to do next" notice ("A check failed." / "This preset
        # passes the model."). The strip has a pinned reason to stay
        # (#119/#146 above the fold) and the banner keeps the count
        # and failed titles for #results landings (#147), so the
        # removable statements were the notice's lead sentence
        # (2026-11-22) and the banner's verdict words (2026-11-23).
        # The notice is next-step content only now; the verdict lives
        # in exactly one place — the strip — in both renderers and
        # both states.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        failed = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertNotIn("A check failed", failed)
        # The banner no longer states the verdict (it lives in the
        # strip only); the notice keeps its CTAs and the banner keeps
        # the count and failed titles.
        self.assertNotIn("SOME FAILED", failed)
        self.assertIn("1 of 6 failed: Donation inflation", failed)
        self.assertIn("/audit/?result=failed", failed)
        self.assertIn("offset 6</a>", failed)
        self.assertIn("/guides/erc4626-slippage-bounds/", failed)
        passed = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertNotIn("This preset passes the model", passed)
        self.assertNotIn("ALL PASS", passed)
        self.assertIn("6 of 6 checks passed", passed)
        self.assertIn("/audit/?result=passed", passed)
        self.assertIn("preset=noprot#results", passed)
        # Worker JS renderer: same openings, no old lead sentences.
        js = build.checker_results_html_js()
        fn = js[js.index("function resultsHTML"):]
        self.assertNotIn("A check failed", fn)
        self.assertNotIn("This preset passes the model", fn)
        self.assertIn("<p>This is a model of the math", fn)
        self.assertIn("<p>Six checks are the floor", fn)

