    def test_form_to_banner_stack_is_tight(self):
        # Checker-improvement (2026-11-22): the form -> banner stack
        # measured 141px at desktop width and 234px at 360px
        # (2026-11-22 02:37, hidden_files/measure-form-banner-gap.py).
        # Two of its layers were slack: the Parameters box forced
        # three lines with <br> (101px desktop / 196px mobile) and
        # the banner carried a 1.2em (30px) top margin. Both halves
        # are pinned here together — the params sentences flow and
        # the banner margin is .6em — in the Python render and the
        # Worker render. Numbers and wording are untouched.
        # Visual verdict #151 (2026-11-22): the banner is stacked
        # now, not a flex row — the margin pin drops the
        # display:flex tail, which the stacked layout overturns.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.checker_body()
        params = html.split("<p class='params'>")[1].split("</p>")[0]
        self.assertNotIn("<br>", params)
        self.assertIn("fee 1000 bps.", params)
        self.assertIn("Victim deposit 100,000 USDC", params)
        # 2026-11-23 (visual verdict #161 item 4): the bar's segments
        # are nowrap spans and the donations/vault-state separators
        # use &nbsp;, so the raw markup no longer reads "Vault state
        # 0 USDC" contiguously — pin the fact on the visible text
        # instead (tags stripped, &nbsp; back to a space), which is
        # what a visitor actually sees.
        visible = re.sub("<[^>]+>", "", params).replace("&nbsp;", " ")
        self.assertIn("Vault state 0 USDC", visible)
        self.assertIn(
            ".result-banner{font-size:1.45em;font-weight:700;"
            "border-radius:8px;padding:.75em 1em;margin:.6em 0}",
            build.CSS)
        self.assertNotIn(
            ".result-banner{font-size:1.45em;font-weight:700;"
            "border-radius:8px;padding:.75em 1em;margin:1.2em 0}",
            build.CSS)
        worker = build.worker_js(
            dict((p, b) for p, t, d, k, b in build.PAGES))
        self.assertIn(
            ".result-banner{font-size:1.45em;font-weight:700;"
            "border-radius:8px;padding:.75em 1em;margin:.6em 0}",
            worker)
        # 2026-11-23 (visual verdict #161 item 4): the Worker copy
        # carries the same nowrap-span structure as the static copy,
        # so the sentence boundaries now run through span tags.
        # 2026-11-24 (#167): the donations list is abbreviated
        # (1, 1K, 1M, 1B) in its own .pseg — the &nbsp; slashes
        # are gone, the exact ladder lives in the donation table.
        self.assertIn("bps.</span> <span class='pseg'>Victim deposit", worker)
        self.assertIn("donations tested 1, 1K, 1M, 1B USDC.</span> Vault state", worker)

