    def test_audit_pay_address_has_basescan_link(self):
        # Visual verdict #103 (2026-11-18): the pay-box had no way to
        # verify the payment address on-chain — a payer about to send 50
        # USDC could only trust the truncated display and the Copy
        # button. The row now carries a "View on BaseScan" link to the
        # full address, so the address and its USDC activity can be
        # checked before paying. A plain link, not a third button: the
        # row already has toggle + copy.
        import sys
        import re
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        audit = dict((p, b) for p, t, d, k, b in build.PAGES)["/audit/"]
        self.assertIn(
            '<a class="basescan-link" href="https://basescan.org/address/'
            + build.PAY_ADDR + '" target="_blank" rel="noopener">'
            'View on BaseScan</a>', audit)
        self.assertIn(".pay-row a.basescan-link{flex-shrink:0;"
                      "white-space:nowrap;font-size:.9em}", build.CSS)
        # Inside the pay-row, after the copy button, before the note.
        row = re.search(r'<div class="pay-row">.*?</div>', audit, re.S)
        self.assertIsNotNone(row, "pay-row not found")
        self.assertLess(row.group(0).index("Copy address"),
                        row.group(0).index("View on BaseScan"))
        self.assertLess(row.group(0).index("View on BaseScan"),
                        row.group(0).index("pay-note"))
        worker = build.worker_js(
            dict((p, b) for p, t, d, k, b in build.PAGES))
        self.assertIn(".pay-row a.basescan-link{flex-shrink:0;", worker)
        self.assertIn("https://basescan.org/address/" + build.PAY_ADDR,
                      worker)
        self.assertIn("View on BaseScan", worker)

    def test_toggle_pay_addr_clears_copy_status(self):
        # Verdict #56: after copying, "Payment address copied." stayed
        # on screen when the address was toggled back to truncated — a
        # stale confirmation next to a now-hidden full address. The
        # toggle must clear the status line on every switch.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        audit = dict((p, b) for p, t, d, k, b in build.PAGES)["/audit/"]
        start = audit.index("function togglePayAddr(btn)")
        body = audit[start:audit.index("</script>", start)]
        self.assertIn("getElementById('pay-copy-status')", body)
        self.assertIn("m.textContent=''", body)
        # The clear must run on every toggle, not only when collapsing
        # back to the truncated form: it precedes the if/else that
        # swaps the display.
        self.assertLess(body.index("pay-copy-status"),
                        body.index("if(el.textContent.trim()===full)"))

    def test_vault_state_hint_names_both_checks(self):
        # The old hint said only the donation check uses vault state;
        # the model docstring says the donation AND minimum-viable-deposit
        # checks use it. Both render paths (Python form + Worker JS form)
        # and the API table must say so; the old wording must be gone.
        # 2026-11-21 (visual verdict #139): the form hint is one line
        # now ("Assets already in the vault. 0 = new."); the
        # both-checks fact moved to the how-to guide Step 1, which the
        # checker notice already links. 2026-11-23 (visual verdict #161
        # item 3): the #139 wording ("Assets already in the vault. 0 =
        # a new vault.", 45 chars) wrapped to 2 lines in the 285px
        # desktop column; the compressed wording keeps the 0 = new
        # vault fact in 37 chars, one line.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        checker = dict((p, b) for p, t, d, k, b in build.PAGES)["/checker/"]
        # The API note ends with a period now: its "; 0 = a new vault"
        # tail was dropped (visual verdict #105 item 5) so the note fits
        # one line at desktop -- the paragraph below the table and the
        # form hint already say 0 means a new vault.
        self.assertIn("Seeds the donation and minimum-viable-deposit checks.",
                      checker)
        self.assertNotIn("minimum-viable-deposit checks; 0 = a new vault",
                         checker)
        self.assertNotIn("Only the donation check uses", checker)
        self.assertNotIn("Seeds only the donation check", checker)
        # The old form sentence is gone entirely (its facts live in the
        # how-to guide now); the guide carries both halves.
        src = (Path.home() / "workspace/taskmarket/site/build.py").read_text()
        self.assertNotIn("The donation and minimum-viable-deposit checks use this, "
                         "and victim loss is measured against it.", src)
        pages = dict((p, b) for p, t, d, k, b in build.PAGES)
        guide = " ".join(
            pages["/guides/how-to-use-the-erc4626-checker/"].split())
        self.assertIn("Only the donation and minimum-viable-deposit checks use them",
                      guide)
        self.assertIn("Victim loss is measured against that state.", guide)

    def test_audit_track_record_groups_fold(self):
        # /audit/ Track record was 40 items in 5 groups rendered as one
        # continuous wall, several screens with no folding or summary
        # (visual verdicts #51/#52). Each group is now a <details> with
        # the group title as its summary: the page scans as five lines.
        # Four groups are closed by default (visual verdict #109
        # item 2): the first group used to stay open, adding ~250px on
        # desktop / ~500px on mobile and pushing "What you do not get"
        # to the 3rd (desktop) / 7th (mobile) viewport. (2026-11-19
        # update: verdict #119 item 3 second half supersedes #109 for
        # the FIRST group only — the strongest proof (Gamma 25/27,
        # BattleChain 9/9, Zaros 66/70) was invisible behind one click
        # on the paid page, so the first group is open by default and
        # the other four stay closed; the 33-item First Flight wall
        # still folds. The first group's summary line still carries
        # the strongest claim, now visible without a click.)
        # (2026-11-20 update: visual verdict #131 item 3 extends the
        # #119 trade to the three SHORT groups — the Bounded slice (3),
        # Reference (1) and Live finding (1) are open by default too,
        # so 8 proof entries show without a click instead of 3. The
        # 33-item First Flight wall stays folded: it is the only group
        # whose open height is a wall. Measured cost of opening the
        # three short groups (headless, static audit page): "What you
        # do not get" moves +424px at 1919px / +1021px at 360px; the
        # added height sits below the order form, so the conversion
        # path is unaffected.)
        # (2026-11-21 update: visual verdict #136 item 3 reverses the
        # #131 fold for the First Flight group — the largest body of
        # evidence (33 reviews) was hidden behind one click on the
        # paid page, and the fold was only justified while the open
        # group was a wall. The entries are now split into a lead
        # line + a smaller detail line with the date on its own line
        # (see test_audit_track_record_entries_split_lead_and_detail),
        # so the open group scans instead of walling. All five groups
        # are now open by default; the added height still sits below
        # the order form, so the conversion path is unaffected.)
        # (2026-11-21 update: visual verdict #138 reverses the #136
        # expansion for the First Flight group ONLY — a fresh-eyes
        # rendered look at the live page (browser-task:0e6384a5,
        # 07:38-07:40) still calls the 33-card single column the
        # ugliest problem on the site: a dense wall, hard to scan,
        # burying "What you do not get" ~4-5 screens down. The
        # lead/detail restructure did not save it; 33 cards are a
        # wall at any density. The other four groups stay open (8
        # proof entries visible without a click, strongest first),
        # and the folded First Flight summary still proves the
        # method at a glance — its preview line names three reviews
        # and the toggle reads "Show 33 reviews". The added height
        # still sits below the order form, so the conversion path
        # is unaffected.)
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        audit = dict((p, b) for p, t, d, k, b in build.PAGES)["/audit/"]
        track = audit[audit.index("<h2>Track record</h2>"):]
        self.assertEqual(track.count('<details class="track-group"'), 5)
        self.assertEqual(track.count("<summary>"), 5)
        self.assertEqual(track.count('<details class="track-group" open>'), 4)
        # Strongest proof first: the ended contests whose full awarded
        # sets were re-verified — open by default (see above), the
        # three short groups with them, and since 2026-11-21 the
        # First Flight group folded again (verdict #138 item 1).
        # Visual verdict #112 item 1: a folded row showed only its
        # title, so each summary now carries a one-line preview of the
        # strongest item(s) inside; the folded state still proves the
        # method at a glance.
        self.assertIn('<details class="track-group" open>\n'
                      '<summary>Full awarded set re-verified — ended contests (3)'
                      '<span class="track-toggle"><span class="when-closed">Show 3 reviews</span>'
                      '<span class="when-open">Hide</span><span class="tri"></span></span>'
                      '<span class="track-preview">Gamma 25 of 27 · BattleChain 9 of 9 · '
                      'Zaros 66 of 70</span></summary>',
                      track)
        # The two ended-contest groups used to share the same leading
        # words ("Ended contests — ...") and differed only in the
        # subtitle after the dash (visual verdicts #107/#108): the
        # distinguishing scope now leads, so the summaries are
        # distinguishable at a glance.
        self.assertIn('<details class="track-group" open>\n'
                      '<summary>Bounded slice — ended contests (3)'
                      '<span class="track-toggle"><span class="when-closed">Show 3 reviews</span>'
                      '<span class="when-open">Hide</span><span class="tri"></span></span>'
                      '<span class="track-preview">RAAC 3 Highs + 1 Medium in 657 lines · '
                      'QuantAMM fee-logic Medium · Nexus 14 findings</span></summary>',
                      track)
        # The 33-item First Flight group is folded by default since
        # 2026-11-21 (visual verdict #138 reversed the #136 expansion
        # — see the comment above). Its heading count is honest:
        # three reviews were added after the (30) heading was written
        # (Vyper Vested Claims, Curve Storage Proofs, SNARKeling), so
        # it now says (33). The folded summary still carries the
        # preview line, so the proof signal survives the fold.
        self.assertIn('<details class="track-group">\n'
                      '<summary>CodeHawks First Flight — practice and study reviews (33)'
                      '<span class="track-toggle"><span class="when-closed">Show 33 reviews</span>'
                      '<span class="when-open">Hide</span><span class="tri"></span></span>'
                      '<span class="track-preview">Thunder Loan (flash-loan drain) · Puppy Raffle '
                      '(9 findings) · Vanguard (router-bucket bypass) · and 30 more</span></summary>',
                      track)
        # The two one-item groups preview their single item, not a count —
        # and both are open by default (2026-11-20, verdict #131 item 3).
        self.assertIn('<details class="track-group" open>\n'
                      '<summary>Reference (1)'
                      '<span class="track-toggle"><span class="when-closed">Show reference</span>'
                      '<span class="when-open">Hide</span><span class="tri"></span></span>'
                      '<span class="track-preview">77 recurring vulnerability patterns, '
                      'each proven by a real finding</span></summary>', track)
        self.assertIn('<details class="track-group" open>\n'
                      '<summary>Live finding (1)'
                      '<span class="track-toggle"><span class="when-closed">Show finding</span>'
                      '<span class="when-open">Hide</span><span class="tri"></span></span>'
                      '<span class="track-preview">Auction clock never enforced — '
                      'forge reproduction 3/3</span></summary>', track)
        self.assertEqual(track.count('<span class="track-preview">'), 5)
        # Preview reads as a subtitle: block, one size down, grey, not bold.
        self.assertIn(".track-group summary .track-preview{display:block;font-size:.85em;"
                      "font-weight:400;color:#6b7280;margin-top:.15em}", build.CSS)
        # Visual verdict #125 (f): the preview repeats the cards' numbers
        # once the group is open, so it hides when open and only shows folded.
        self.assertIn(".track-group[open] summary .track-preview{display:none}",
                      build.CSS)
        self.assertNotIn("(32)</summary>", track)
        # No group lost its items: 3 + 33 + 3 + 1 + 1 = 41 research links
        # inside the five details blocks, and no bare h3 survives in the
        # Track record section.
        self.assertEqual(track.count('<a href="/research/'), 41)
        self.assertNotIn("<h3>", track)
        # Summary reads like the h3 it replaces.
        self.assertIn(".track-group summary{cursor:pointer;font-size:1.1em;"
                      "font-weight:700;color:#111827}", build.CSS)
        self.assertIn(".track-group .track-list{margin-top:.4em;margin-bottom:0}", build.CSS)

    def test_audit_track_record_entries_carry_review_dates(self):
        # Visual verdict #131 item 3 (2026-11-20): every Track record
        # entry was dateless — a buyer could not tell whether a review
        # was done last week or last year. Each of the 41 entries now
        # carries the date its review was completed, as stated on the
        # review's own page. Rule: the "done" date in the page intro;
        # where the page states a different completion verb, that date
        # (Gamma/BattleChain/Zaros: read/checked/extracted Nov 15;
        # Dutch clock: submitted Oct 26; playbook: distilled Oct-Nov).
        # Thunder Loan is the one judgment call: its page says "done
        # Oct 10, 2026 with the proofs completed Nov 15, 2026" — the
        # review (findings + proofs) was complete Nov 15, so Nov 15.
        # AirDropper's page states only a month ("done Oct 2026"), so
        # its entry is month-only; ranges keep the page's own range.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        audit = dict((p, b) for p, t, d, k, b in build.PAGES)["/audit/"]
        track = audit[audit.index("<h2>Track record</h2>"):]
