    def test_audit_track_record_entries_split_lead_and_detail(self):
        # Visual verdict #136 item 3 (2026-11-21): Track record entries
        # were dense single paragraphs — title + counts + findings +
        # tests in one run, the date pasted at the sentence end. Each
        # entry then split at its first top-level ';' into a lead line
        # (title + counts + proof, a complete sentence) and a smaller,
        # muted detail line; the date floats at the top-right of the
        # title row (visual verdict #137, 2026-11-21 — see the CSS in
        # test_audit_track_record_entries_carry_review_dates).
        # Visual verdict 2026-11-22 (real browser, desktop 1919x998):
        # #136's split was not enough — the title row still carried
        # title + pill + the whole lead sentence + the floated date in
        # one paragraph, the ugliest block on the site. The lead now
        # has its own full-width block line too, so each entry scans
        # as title row / lead / detail. Only the markup changes: the
        # ' — ' separator is gone, the lead text is byte-identical
        # (same words, same final '.'), the detail is untouched.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        audit = dict((p, b) for p, t, d, k, b in build.PAGES)["/audit/"]
        track = audit[audit.index("<h2>Track record</h2>"):]
        self.assertEqual(track.count('<span class="track-lead">'), 41)
        self.assertEqual(track.count('<span class="track-detail">'), 39)
        self.assertEqual(track.count('<span class="track-date">'), 41)
        # The two entries with no detail span (Gamma, Dutch clock)
        # still carry a lead span — only the detail line is absent.
        for slug in ("gamma", "dutch-clock"):
            m = re.search(r'<li><span class="track-date">Reviewed [^<]*</span>'
                          r'<a href="/research/%s/">.*?</li>'
                          % re.escape(slug), track, re.S)
            self.assertIsNotNone(m, slug)
            self.assertNotIn('<span class="track-detail">', m.group(0), slug)
            self.assertIn('<span class="track-lead">', m.group(0), slug)
        # Every entry: the date span is source-first in the <li>
        # (floated to the title row's right), and every split entry's
        # lead ends with '.' right before the detail span, the detail
        # ends with '.' and closes the entry.
        for m in re.finditer(r'<li><span class="track-date">Reviewed [^<]*</span>'
                             r'<a href="/research/[^"]+/">.*?</li>',
                             track, re.S):
            entry = m.group(0)
            self.assertRegex(entry,
                             r'<li><span class="track-date">Reviewed [^<]*'
                             r'</span><a href="/research/',
                             entry[:80])
            if '<span class="track-detail">' not in entry:
                continue
            self.assertRegex(entry,
                             r'</a>(?:<span class="track-findings">[^<]*</span>)?'
                             r'<span class="track-lead">[^<]*\.\s*</span>\s*'
                             r'<span class="track-detail">',
                             entry[:80])
            self.assertRegex(entry,
                             r'<span class="track-detail">[^<]*\.</span></li>',
                             entry[:80])
        # Spot checks: the leads are complete sentences, details intact.
        self.assertIn('<a href="/research/thunder-loan/">Thunder Loan</a>'
                      '<span class="track-findings">4 findings · 3H 1M</span>'
                      '<span class="track-lead">four flash-loan findings, all '
                      'forge-proven (3 High, '
                      '1 Medium graded High by the canonical report). </span>'
                      '<span class="track-detail">6 of 7 canonical High+Medium '
                      'findings independently reproduced (four forge-proven, '
                      'two code-read), the seventh — the '
                      'fee-on-transfer Medium — never considered, 15/15 tests '
                      'passing.</span>', track)
        self.assertIn('<a href="/research/zaros/">Zaros Part 2</a>'
                      '<span class="track-findings">66 re-verified · 15H 32M 19L</span>'
                      '<span class="track-lead">66 of 70 '
                      'awarded findings re-derived (16 High, 35 Medium, '
                      '19 Low; $70,000 pool), four presented as MISSes (1 High, '
                      '3 Medium). </span>'
                      '<span class="track-detail">forge PoCs for M-NEGCAP 2/2, '
                      'M-PDINV 3/3, M-PDSET 5/5.</span>', track)
        # Visual verdict #145 (2026-11-21): Gamma was the first "N of M"
        # entry found leaving the missing findings' fate unstated — the
        # reader had to compute 27-25=2 and guess what happened to
        # them. Zaros already said "four presented as MISSes"; Gamma
        # now says the same for its two (M-05 and L-12, per the Gamma
        # page table — see
        # test_audit_track_record_entries_carry_findings_labels).
        self.assertRegex(
            track,
            r'<a href="/research/gamma/">Gamma Perpetual Vault</a>'
            r'<span class="track-findings">25 re-verified · 5H 8M 12L</span>'
            r'<span class="track-lead">25 of 27 validated\s+contest findings re-verified '
            r'\(5 High, 9 Medium, 13 Low; \$50,000 pool\), two presented '
            r'as MISSes \(1 Medium, 1 Low\), four with\s+forge PoCs, one live on-chain\.</span></li>')
        # 2026-11-21 22:37, full audit of all 41 Track record entries:
        # the 21:37 round's "Gamma was the only one" was incomplete —
        # Thunder Loan's "6 of 7" also left the seventh's fate
        # unstated. The seventh is canonical M-03, the fee-on-transfer
        # Medium (CodeHawks record: validated Medium — deposit mints
        # on the nominal amount while a fee token delivers less); the
        # Thunder Loan page's own "Missed" section says it was never
        # considered. The /audit/ line, the /research/ index line,
        # and the Thunder Loan page's summary + intro now all say so.
        # Every other "N of M" entry already states the remainder's
        # fate (Zaros MISSes; BattleChain 9/9 complete; Puppy/Santa/
        # Beatland/DatingDapp/Algo/Rust Fund name the missed finding;
        # Snowman says the two missed were packaged with fresh PoCs;
        # MyCut says 6 missed in return; AirDropper says
        # judge-invalidated).
        self.assertRegex(
            track,
            r'<a href="/research/thunder-loan/">Thunder Loan</a>'
            r'<span class="track-findings">4 findings · 3H 1M</span>'
            r'<span class="track-lead">four flash-loan findings, all forge-proven \(3 High, '
            r'1 Medium graded High by the canonical report\)\.\s*</span>'
            r'<span class="track-detail">6 of 7 canonical High\+Medium '
            r'findings independently reproduced \(four forge-proven, '
            r'two code-read\), the seventh — the '
            r'fee-on-transfer Medium — never considered, 15/15 tests '
            r'passing\.</span>')
        self.assertIn(".track-detail{display:block;font-size:.92em;"
                      "color:#4b5563;margin-top:.6em}", build.CSS)
        self.assertIn(".track-lead{display:block;margin-top:.45em}",
                      build.CSS)

    def test_track_record_miss_severities_are_stated(self):
        # Visual verdict #144 (2026-11-21): the Track record entries
        # said "two/four presented as MISSes" but not WHICH severities
        # — the reader still had to subtract the pill split from the
        # contest split (Gamma 27-25, Zaros 70-66) to learn the misses
        # were 1M+1L and 1H+3M. Verdict #145 had already fixed the
        # misses' FATE (presented as MISSes, not silently dropped);
        # this states their severities in the sentence itself.
        # Ground truth is the review pages' own MISS sections, not
        # just the arithmetic: Gamma names M-05 (Medium) and L-12
        # (Low); Zaros names H-LPREDEEM (High) and M-FEEDIST,
        # M-OWNABLEINIT, M-CONNVAULT (Mediums).
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        pages = dict((p, b) for p, t, d, k, b in build.PAGES)
        audit = pages["/audit/"]
        self.assertIn("two presented as MISSes (1 Medium, 1 Low)", audit)
        self.assertIn("four presented as MISSes (1 High, 3 Medium)", audit)
        # The severities must reconcile: pill split + miss split =
        # contest split, so a future edit cannot silently break the
        # count the entry itself states.
        gamma = pages["/research/gamma/"]
        self.assertIn("M-05 — presented as a MISS, not a finding", gamma)
        self.assertIn("L-12 — presented as a MISS, not a finding", gamma)
        zaros = pages["/research/zaros/"]
        self.assertIn("H-LPREDEEM", zaros)
        for mid in ("M-FEEDIST", "M-OWNABLEINIT", "M-CONNVAULT"):
            self.assertIn(mid, zaros)
        self.assertIn("Four groups are presented as <strong>MISSes</strong>", zaros)
        # The severities must reconcile against the page itself: pill
        # split (re-verified) + miss split = contest split, so a future
        # edit cannot silently break the count the entry itself states.
        def splits(slug, miss_re, miss_map):
            m = re.search(
                r'<a href="/research/%s/">.*?<span class="track-findings">'
                r'(\d+) (?:findings|re-verified) · (\d+)H (\d+)M (\d+)L</span>'
                % re.escape(slug), audit, re.S)
            self.assertIsNotNone(m, slug)
            pill = tuple(int(x) for x in m.groups()[1:])
            m = re.search(
                r'(\d+) High, (\d+) Medium, (\d+) Low', audit[m.start():])
            self.assertIsNotNone(m, slug)
            contest = tuple(int(x) for x in m.groups())
            m = re.search(miss_re, audit[m.start():])
            self.assertIsNotNone(m, slug)
            miss = miss_map(tuple(int(x) for x in m.groups()))
            return pill, miss, contest
        for slug, miss_re, miss_map in (
                ("gamma",
                 r'two presented as MISSes \((\d+) Medium, (\d+) Low\)',
                 lambda g: (0, g[0], g[1])),
                ("zaros",
                 r'four presented as MISSes \((\d+) High, (\d+) Medium\)',
                 lambda g: (g[0], g[1], 0))):
            pill, miss, contest = splits(slug, miss_re, miss_map)
            self.assertEqual(tuple(p + m for p, m in zip(pill, miss)),
                             contest)

