    def test_harvest_timing_carries_cache_variant_defenses(self):
        # Reflection #297: the stale-total-assets-cache model is a
        # partial collision with harvest-timing #32 S1 (same stale-price
        # transfer, 50,000 gain -> 4,545.454545 at half the scale), so
        # its defense quantifications (model legs C/D/E) belong in the
        # harvest-timing guide as a "cached totalAssets" variant section
        # instead of living only in the standalone guide. The section
        # must carry the exact model figures: 100,000 yield in the
        # cache window mints 100,000 vs fair 90,909.090909 and gains
        # 9,090.909091; live-balance pricing mints 90,909 (dust 1/11
        # share) and redeems 99,999.908333, bounding extraction under
        # 1 USDC; syncing the cache mints the same 90,909; a 10,000
        # yield window gains 909.090909 (exactly 1/10); harvest-first
        # mints 99,009 and zeroes the window.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        pages = dict((p, b) for p, t, d, k, b in build.PAGES)
        guide = pages["/guides/erc4626-harvest-timing/"]
        self.assertIn("cached totalAssets", guide)
        self.assertIn("90,909.090909", guide)
        self.assertIn("109,090.909091", guide)
        self.assertIn("9,090.909091", guide)
        self.assertIn("99,999.908333", guide)
        self.assertIn("909.090909", guide)
        self.assertIn("99,009", guide)
        self.assertIn("/guides/erc4626-stale-total-assets-cache/", guide)
        # The original harvest-timing numbers survive the merge.
        self.assertIn("4,545.454545", guide)
        self.assertIn("2,222.222221", guide)

    def test_stale_total_assets_cache_guide_numbers(self):
        # Stale totalAssets cache guide (site/stale-total-assets-cache-
        # model.py): a vault that prices off a stored totalAssets
        # snapshot, updated only at harvest. Re-derived here with plain
        # fractions.Fraction arithmetic, independent of the model file,
        # so the guide's numbers cannot drift silently. Vault
        # 1,000,000 USDC / 1,000,000 shares at $1.00, Alice holding
        # all 1,000,000 shares.
        from fractions import Fraction
        S = Fraction(1_000_000)
        dep = Fraction(100_000)

        # A: yield 100,000, live 1,100,000, cache 1,000,000. Deposit
        # mints 100,000 shares against a fair 1,000,000/11; after the
        # refresh (live 1,200,000, supply 1,100,000, price 12/11) the
        # depositor holds 1,200,000/11, gaining 100,000/11, and Alice
        # loses exactly that much.
        fair_a = dep * S / Fraction(1_100_000)
        self.assertEqual(fair_a, Fraction(1_000_000, 11))
        self.assertEqual(Fraction(100_000) - fair_a, Fraction(100_000, 11))
        self.assertEqual((100_000 * 1_000_000) // 1_000_000
                         - (100_000 * 1_000_000) // 1_100_000, 9_091)
        val_a = Fraction(100_000) * Fraction(1_200_000, 1_100_000)
        self.assertEqual(val_a, Fraction(1_200_000, 11))
        self.assertEqual(val_a - dep, Fraction(100_000, 11))
        self.assertEqual(Fraction(1_000_000) * Fraction(1_200_000, 1_100_000),
                         Fraction(12_000_000, 11))

        # B: loss 100,000, live 900,000, cache 1,000,000. A redeemer
        # takes 100,000 for shares worth 90,000 (+10,000); the late
        # depositor buys 100,000 shares against a fair 1,000,000/9 and
        # after the refresh (live 1,000,000, supply 1,100,000, price
        # 10/11) holds 1,000,000/11, losing 100,000/11, which Alice
        # gains.
        self.assertEqual(Fraction(100_000) * Fraction(900_000) / S,
                         90_000)
        fair_b = dep * S / Fraction(900_000)
        self.assertEqual(fair_b, Fraction(1_000_000, 9))
        self.assertEqual(fair_b - dep, Fraction(100_000, 9))
        val_b = dep * Fraction(1_000_000, 1_100_000)
        self.assertEqual(val_b, Fraction(1_000_000, 11))
        self.assertEqual(dep - val_b, Fraction(100_000, 11))

        # C: live-balance pricing mints floor(100,000e6 / 1.1e6) =
        # 90,909 shares, 1/11 of a share short of fair, and redeeming
        # after the refresh returns 99,999.908333... -- extraction
        # bounded by 1 USDC.
        mint_c = (100_000 * 1_000_000) // 1_100_000
        self.assertEqual(mint_c, 90_909)
        self.assertEqual(Fraction(1_000_000, 11) - mint_c, Fraction(1, 11))
        red_c = Fraction(mint_c) * Fraction(1_200_000, 1_000_000 + mint_c)
        self.assertEqual(red_c, Fraction(109_090_800_000, 1_090_909))
        self.assertLess(100_000 - red_c, 1)

        # E: only 10,000 of yield in the window. Fair shares
        # 100,000,000/1,010, excess 1,000,000/1,010, gain 10,000/11 --
        # exactly one tenth of A's 100,000/11. A harvest immediately
        # before the deposit mints 99,009 shares.
        fair_e = dep * S / Fraction(1_010_000)
        self.assertEqual(fair_e, Fraction(100_000_000, 1_010))
        self.assertEqual(dep - fair_e, Fraction(1_000_000, 1_010))
        gain_e = dep * Fraction(1_110_000, 1_100_000) - dep
        self.assertEqual(gain_e, Fraction(10_000, 11))
        self.assertEqual(gain_e, Fraction(100_000, 11) / 10)
        self.assertEqual((100_000 * 1_000_000) // 1_010_000, 99_009)

        # The guide's six-decimal displays are ROUNDED, not truncated:
        # 100,000/11 truncates to 9,090.909090 but the guide (and the
        # model, which formats with f"{x:,.6f}") shows 9,090.909091;
        # 1,200,000/11 truncates to 109,090.909090, shown as
        # 109,090.909091; 1,000,000/1,010 truncates to 990.099009,
        # shown as 990.099010. The intro sentence must say so.
        for fr, shown in ((Fraction(100_000, 11), "9,090.909091"),
                          (Fraction(1_200_000, 11), "109,090.909091"),
                          (Fraction(1_000_000, 1_010), "990.099010")):
            trunc = fr.numerator * 10**6 // fr.denominator
            trunc_str = f"{trunc // 1_000_000:,}.{trunc % 1_000_000:06d}"
            self.assertNotEqual(trunc_str, shown)
            r = round(fr * 10**6)
            round_str = f"{r // 1_000_000:,}.{r % 1_000_000:06d}"
            self.assertEqual(round_str, shown)

    def test_stale_total_assets_cache_guide_page(self):
        # Pins the guide page: the add() must exist with the headline
        # numbers, the corrected display-convention sentence, and a
        # link from the /guides/ index. The numbers are re-derived in
        # test_stale_total_assets_cache_guide_numbers; this pins the
        # page. The old "truncated" sentence must be gone from this
        # guide's block (the same boilerplate still stands in other
        # guides, each to be verified on its own round).
        from pathlib import Path
        build = (Path.home() / "workspace/taskmarket/site/build.py"
                 ).read_text()
        self.assertIn('"/guides/erc4626-stale-total-assets-cache/"', build)
        for num in ("90,909.090909", "9,090.909091", "109,090.909091",
                    "1,090,909.090909", "111,111.111111", "11,111.111111",
                    "90,909.090909", "99,999.908333", "99,009.900990",
                    "990.099010", "909.090909", "99,009"):
            self.assertIn(num, build)
        self.assertIn("shown rounded to six decimals", build)
        start = build.index('add("/guides/erc4626-stale-total-assets-cache/"')
        end = build.index('add("/guides/erc4626-treasury-self-holding/"')
        self.assertLess(start, end)
        block = build[start:end]
        self.assertNotIn("shown truncated to six decimals", block)
        self.assertIn("shown rounded to six decimals", block)
        self.assertIn('<a href="/guides/erc4626-stale-total-assets-cache/">',
                      build)

    def test_reward_token_guide_numbers(self):
        # Reward-token guide (site/reward-token-model.py): yield paid
        # out as a separate token never touches the share price.
        # Re-derived here with plain integer / Fraction arithmetic,
        # independent of the model file. Vault 100,000 USDC / 100,000
        # shares, price 1.00; Alice 50,000 shares, others 50,000.
        USDC = 1_000_000
        A0, S0 = 100_000 * USDC, 100_000 * USDC
        ALICE, OTHERS = 50_000 * USDC, 50_000 * USDC
        YIELD = 10_000 * USDC
        # 1: price stays exactly 1.00 through the distribution.
        self.assertEqual(Fraction(A0, S0), 1)
        # 2: Bob deposits 100,000 after the yield accrued, before
        # distribution. No checkpoint: reward/share 0.05, Alice 2,500,
        # others 2,500, Bob 5,000. With checkpoint: Alice 5,000,
        # others 5,000, Bob 0. Late entry costs Alice 2,500.
        S1 = S0 + 100_000 * USDC
        rps = Fraction(YIELD, S1)
        self.assertEqual(rps, Fraction(1, 20))
        self.assertEqual((ALICE * rps, OTHERS * rps, 100_000 * USDC * rps),
                         (2_500 * USDC, 2_500 * USDC, 5_000 * USDC))
        self.assertEqual((YIELD * ALICE // S0, YIELD * OTHERS // S0),
                         (5_000 * USDC, 5_000 * USDC))
        self.assertEqual(5_000 * USDC - 2_500 * USDC, 2_500 * USDC)
        # 3: second 10,000 distribution after Bob joined: Alice 2,500,
        # others 2,500, Bob 5,000 under both policies. Totals:
        # checkpoint Alice 7,500 / Bob 5,000; no checkpoint Alice
        # 5,000 / Bob 10,000.
        rps2 = Fraction(YIELD, S1)
        self.assertEqual((ALICE * rps2, OTHERS * rps2,
                          100_000 * USDC * rps2),
                         (2_500 * USDC, 2_500 * USDC, 5_000 * USDC))
        self.assertEqual((5_000 * USDC + 2_500 * USDC, 5_000 * USDC),
                         (7_500 * USDC, 5_000 * USDC))
        self.assertEqual((2_500 * USDC + 2_500 * USDC,
                          5_000 * USDC + 5_000 * USDC),
                         (5_000 * USDC, 10_000 * USDC))
        # 4: Alice redeems 50,000 shares for 50,000 USDC; her 5,000
        # REWARD claim is separate -- 10% of the position, walked
        # away from if never claimed.
        self.assertEqual(ALICE * Fraction(A0, S0), 50_000 * USDC)
        self.assertEqual(Fraction(5_000 * USDC, 50_000 * USDC),
                         Fraction(1, 10))
        # 5: reward-token price risk: 5,000 REWARD at 0.50 USDC is
        # worth 2,500 USDC.
        self.assertEqual(5_000 * USDC * Fraction(1, 2), 2_500 * USDC)

    def test_tranched_vault_guide_numbers(self):
        # Tranched-vault guide (site/tranche-vault-model.py): senior
        # 60,000 shares promised fixed 5% per period, junior 40,000
        # shares takes the residual and absorbs losses first. Vault
        # 100,000 USDC / 100,000 shares, both tranches at 1.00.
        # Re-derived here with plain integer / Fraction arithmetic,
        # independent of the model file.
        USDC = 1_000_000
        # 1: yield +10,000: senior takes 5% of 60,000 = 3,000, junior
        # the residual 7,000. Prices 1.05 / 1.175; blended 1.10.
        self.assertEqual(60_000 * USDC * 5 // 100, 3_000 * USDC)
        self.assertEqual(10_000 * USDC - 3_000 * USDC, 7_000 * USDC)
        self.assertEqual(Fraction(63_000 * USDC, 60_000), Fraction(21, 20) * USDC)
        self.assertEqual(Fraction(47_000 * USDC, 40_000), Fraction(47, 40) * USDC)
        self.assertEqual(Fraction(110_000 * USDC, 100_000), Fraction(11, 10) * USDC)
        self.assertEqual(66_000 * USDC - 63_000 * USDC, 3_000 * USDC)
        # 2: loss -10,000: junior absorbs it all. Prices 1.00 / 0.75.
        self.assertEqual(Fraction(60_000 * USDC, 60_000), 1 * USDC)
        self.assertEqual(Fraction(30_000 * USDC, 40_000), Fraction(3, 4) * USDC)
        self.assertEqual(60_000 * USDC // 10, 6_000 * USDC)
        # 3: loss -50,000: junior wiped to 0, senior takes the excess
        # 10,000 = one sixth of senior capital; price 5/6.
        self.assertEqual(max(40_000 * USDC - 50_000 * USDC, 0), 0)
        self.assertEqual(Fraction(50_000 * USDC, 60_000), Fraction(5, 6) * USDC)
        self.assertEqual(Fraction(10_000, 60_000), Fraction(1, 6))
        self.assertEqual(10_000 * Fraction(50_000 * USDC, 60_000),
                         Fraction(25_000, 3) * USDC)
        # 4: shortfall: yield +2,000 < promised 3,000. Senior 62,000
        # (price 31/30), junior 40,000 (1.00), shortfall 1,000 carried.
        self.assertEqual(3_000 * USDC - 2_000 * USDC, 1_000 * USDC)
        self.assertEqual(Fraction(62_000 * USDC, 60_000), Fraction(31, 30) * USDC)
        # Next +10,000: senior takes 1,000 + 3,000 = 4,000, junior 6,000.
        self.assertEqual(Fraction(66_000 * USDC, 60_000), Fraction(11, 10) * USDC)
        self.assertEqual(Fraction(46_000 * USDC, 40_000), Fraction(23, 20) * USDC)
        self.assertEqual(66_000 * USDC + 46_000 * USDC, 112_000 * USDC)
        # 5: new 10,000 deposit after the +10% period mints 200,000/21
        # senior shares or 400,000/47 junior shares, both worth 10,000.
        self.assertEqual(Fraction(10_000 * USDC, Fraction(21, 20) * USDC),
                         Fraction(200_000, 21))
        self.assertEqual(Fraction(10_000 * USDC, Fraction(47, 40) * USDC),
                         Fraction(400_000, 47))

    def test_tiered_fee_guide_numbers(self):
        # Guide #48: tiered deposit fee -- 5% below 10,000, 2% from
        # 10,000, 1% from 100,000 (per deposit call, on gross).
        # Re-derived here with plain integer / Fraction arithmetic,
        # independent of the model file.
        USDC = 1_000_000
        # A: 5,000 at 5% -> fee 250, net 4,750.
        self.assertEqual(5_000 * USDC * 5 // 100, 250 * USDC)
        # B/C: the 10,000 cliff -- 1 more USDC in, 300.95 more net out.
        self.assertEqual(9_999 * USDC * 5 // 100, Fraction(9999, 20) * USDC)
        self.assertEqual(9_999 * USDC - Fraction(9999, 20) * USDC,
                         Fraction(189981, 20) * USDC)
        self.assertEqual(10_000 * USDC * 2 // 100, 200 * USDC)
        self.assertEqual(Fraction(9_800) - Fraction(189981, 20),
                         Fraction(6019, 20))
        # D/E: the 100,000 cliff -- 1 more USDC in, 1,000.98 more net out.
        self.assertEqual(99_999 * USDC * 2 // 100, Fraction(99999, 50) * USDC)
        self.assertEqual(99_999 * USDC - Fraction(99999, 50) * USDC,
                         Fraction(4899951, 50) * USDC)
        self.assertEqual(100_000 * USDC * 1 // 100, 1_000 * USDC)
        self.assertEqual(Fraction(99_000) - Fraction(4899951, 50),
                         Fraction(50049, 50))
        # F: 200,000 at 1% -> fee 2,000, net 198,000.
        self.assertEqual(200_000 * USDC // 100, 2_000 * USDC)
        # Tiering vs flat 5%: saves 300 on 10,000, 4,000 on 100,000.
        self.assertEqual(10_000 * USDC * 5 // 100 - 200 * USDC, 300 * USDC)
        self.assertEqual(100_000 * USDC * 5 // 100 - 1_000 * USDC, 4_000 * USDC)
        # G: splitting 10,000 into 2x5,000 costs 300 extra in fees;
        # splitting inside one tier (2x10,000 vs 20,000) costs nothing.
        self.assertEqual(2 * (5_000 * USDC * 5 // 100) - 200 * USDC, 300 * USDC)
        self.assertEqual(2 * (10_000 * USDC * 2 // 100),
                         20_000 * USDC * 2 // 100)
        # H: cliff in shares at price 1.10: 9,999 -> 8,635.50 shares,
        # 10,000 -> 8,909.090909... shares, cliff 6,019/22 shares.
        self.assertEqual(Fraction(9_499_05, 100) / Fraction(11, 10),
                         Fraction(17_271, 2))
        self.assertEqual(Fraction(9_800) / Fraction(11, 10),
                         Fraction(98_000, 11))
        self.assertEqual(Fraction(98_000, 11) - Fraction(17_271, 2),
                         Fraction(6_019, 22))
        # Boundary exactness: exactly 10,000 / 100,000 get the lower rate.
        self.assertEqual(10_000 * USDC * 2 // 100, 200 * USDC)
        self.assertEqual(100_000 * USDC * 1 // 100, 1_000 * USDC)

    def test_insurance_reserve_guide_numbers(self):
        # Guide #49: insurance-reserve vault -- a 5,000 USDC reserve held
        # outside totalAssets tops the vault up after a loss, up to the
        # reserve balance. Vault 100,000 USDC / 100,000 shares, price 1.00;
        # Alice holds 50,000 shares. Re-derived here with plain integer /
        # Fraction arithmetic, independent of the model file.
        USDC = 1_000_000
        # 1: loss -3,000, reserve pays all 3,000: assets back to 100,000,
        # price 1.00, reserve left 2,000. Alice loses 0; without the
        # reserve she would hold 48,500 (price 0.97), losing 1,500.
        self.assertEqual(min(3_000 * USDC, 5_000 * USDC), 3_000 * USDC)
        self.assertEqual(5_000 * USDC - 3_000 * USDC, 2_000 * USDC)
        self.assertEqual(100_000 * USDC - 3_000 * USDC + 3_000 * USDC,
                         100_000 * USDC)
        self.assertEqual(50_000 * Fraction(97_000 * USDC, 100_000),
                         48_500 * USDC)
        # 2: loss -10,000, reserve has 2,000 left: pays 2,000, assets
        # 92,000, price 23/25 = 0.92, Alice 46,000. Without the reserve
        # the price would be 0.90 and Alice would hold 45,000.
        self.assertEqual(min(10_000 * USDC, 2_000 * USDC), 2_000 * USDC)
        self.assertEqual(100_000 * USDC - 10_000 * USDC + 2_000 * USDC,
                         92_000 * USDC)
        self.assertEqual(Fraction(92_000 * USDC, 100_000),
                         Fraction(23, 25) * USDC)
        self.assertEqual(50_000 * Fraction(92_000 * USDC, 100_000),
                         46_000 * USDC)
        self.assertEqual(50_000 * Fraction(90_000 * USDC, 100_000),
                         45_000 * USDC)
        # 3: gain +4,000. Refill-first: reserve 4,000, vault stays 92,000,
        # price 0.92. Distribute-first: reserve 0, vault 96,000, price
        # 24/25 = 0.96. Alice redeeming 50,000 shares gets 46,000 vs
        # 48,000 -- a 2,000 difference. The next -4,000 loss makes both
        # policies converge at 92,000 / 0.92.
        self.assertEqual(min(0 + 4_000 * USDC, 5_000 * USDC), 4_000 * USDC)
        self.assertEqual(Fraction(96_000 * USDC, 100_000),
                         Fraction(24, 25) * USDC)
        self.assertEqual(48_000 * USDC - 46_000 * USDC, 2_000 * USDC)
        self.assertEqual(92_000 * USDC - 4_000 * USDC + 4_000 * USDC,
                         92_000 * USDC)
        self.assertEqual(96_000 * USDC - 4_000 * USDC + 0,
                         92_000 * USDC)
        # 4: one big loss -50,000 with a full 5,000 reserve: assets 55,000,
        # price 11/20 = 0.55, Alice 27,500. Without the reserve: price
        # 0.50, Alice 25,000 -- the reserve saves 2,500 of a 25,000 loss.
        self.assertEqual(min(50_000 * USDC, 5_000 * USDC), 5_000 * USDC)
        self.assertEqual(100_000 * USDC - 50_000 * USDC + 5_000 * USDC,
                         55_000 * USDC)
        self.assertEqual(Fraction(55_000 * USDC, 100_000),
                         Fraction(11, 20) * USDC)
        self.assertEqual(50_000 * Fraction(55_000 * USDC, 100_000),
                         27_500 * USDC)
        self.assertEqual(27_500 * USDC - 25_000 * USDC, 2_500 * USDC)
        self.assertEqual(Fraction(5_000, 100_000), Fraction(1, 20))
        # 5: funding: 5,000 / 0.5% = 1,000,000 USDC of deposits; 1% of a
        # 10,000 annual yield = 100/year, so 5,000 takes 50 years.
        self.assertEqual(5_000 * USDC * 1000 // 5, 1_000_000 * USDC)
        self.assertEqual(10_000 * USDC // 100, 100 * USDC)
        self.assertEqual(5_000 * USDC // (100 * USDC), 50)

    def test_yield_token_guide_numbers(self):
        # Guide #51: yield-token vault (ERC-5115) -- 10,000 SY splits
        # 1:1:1 into 10,000 PT + 10,000 YT. Vault 100,000 USDC /
        # 100,000 SY, price 1.00, maturity one year out; Alice holds
        # 10,000 SY. Re-derived here with plain integer / Fraction
        # arithmetic, independent of the model file
        # (site/yield-token-model.py).
        USDC = 1_000_000
        # 1: the split. 10,000 SY -> 10,000 PT + 10,000 YT; at +10%
        # the YT pays 1,000. Hold both to maturity: 11,000, exactly
        # what holding the SY would have been worth.
        self.assertEqual(10_000 * USDC, 10_000 * USDC)
        self.assertEqual(10_000 * USDC * Fraction(1, 10), 1_000 * USDC)
        self.assertEqual(10_000 * USDC + 1_000 * USDC,
                         10_000 * USDC * (1 + Fraction(1, 10)))
        # 2: PT price at 10% implied: 10,000 / 1.10 = 100,000/11 USDC
        # = 9,090.909091; discount 10,000/11 = 909.090909. YT price
        # the same 909.090909; PT + YT = 10,000 = the SY value.
        self.assertEqual(Fraction(10_000 * USDC, 1) / Fraction(11, 10),
                         Fraction(100_000 * USDC, 11))
        self.assertEqual(10_000 * USDC - Fraction(100_000 * USDC, 11),
                         Fraction(10_000 * USDC, 11))
        self.assertEqual(Fraction(1_000 * USDC, 1) / Fraction(11, 10),
                         Fraction(10_000 * USDC, 11))
        self.assertEqual(Fraction(100_000 * USDC, 11)
                         + Fraction(10_000 * USDC, 11),
                         10_000 * USDC)
        # 3: PT gain locked: 10,000 - 100,000/11 = 10,000/11, exactly
        # 10% of the PT price, whatever the vault earns.
        self.assertEqual(10_000 * USDC - Fraction(100_000 * USDC, 11),
                         Fraction(10_000 * USDC, 11))
        self.assertEqual(Fraction(Fraction(10_000 * USDC, 11),
                                  Fraction(100_000 * USDC, 11)),
                         Fraction(1, 10))
        # 4: YT at +5% pays 500; loss 909.090909 - 500 = 409.090909
        # = 4,500/11 USDC, which is 9/20 = -45% of the YT price.
        # At 0% the YT pays 0: the whole 909.090909 is lost (-100%).
        # After maturity the YT is worth exactly 0.
        self.assertEqual(10_000 * USDC * Fraction(1, 20), 500 * USDC)
        self.assertEqual(Fraction(10_000 * USDC, 11) - 500 * USDC,
                         Fraction(4_500 * USDC, 11))
        self.assertEqual(Fraction(Fraction(4_500 * USDC, 11),
                                  Fraction(10_000 * USDC, 11)),
                         Fraction(9, 20))
        self.assertEqual(Fraction(10_000 * USDC, 11) - 0,
                         Fraction(10_000 * USDC, 11))
        # 5: PT quoted at 9,500 implies 10,000/9,500 - 1 = 1/19
        # = 5.263158%. The PT buyer still only gets 10,000 even if
        # the vault earns 10%.
        self.assertEqual(Fraction(10_000 * USDC, 9_500 * USDC) - 1,
                         Fraction(1, 19))
        # 6: sell the YT early at 909.090909, cash idle, PT redeems
        # 10,000: total 120,000/11 = 10,909.090909, short of holding
        # by 1,000/11 = 90.909091.
        self.assertEqual(10_000 * USDC + Fraction(10_000 * USDC, 11),
                         Fraction(120_000 * USDC, 11))
        self.assertEqual(11_000 * USDC - Fraction(120_000 * USDC, 11),
                         Fraction(1_000 * USDC, 11))
        # 7: double-count bug: PT at face 10,000 + YT at expected
        # 1,000 = 11,000 against 10,000 SY of backing -- 1,000
        # overstated, 1/10 = 10%.
        self.assertEqual(10_000 * USDC + 1_000 * USDC, 11_000 * USDC)
        self.assertEqual(11_000 * USDC - 10_000 * USDC, 1_000 * USDC)
        self.assertEqual(Fraction(1_000 * USDC, 10_000 * USDC),
                         Fraction(1, 10))
        # 8: SY price blind spot: totalAssets stays 100,000 through
        # a +10% year, price exactly 1.00.
        self.assertEqual(Fraction(100_000 * USDC, 100_000 * USDC), 1)

    def test_share_classes_guide_numbers(self):
        # Guide #50: two share classes, one vault -- A pays 2%, B pays
        # 0.5%. Each class holds 500,000 shares / 500,000 USDC at launch,
        # price 1.00. Alice holds 10,000 shares. Re-derived here with
        # plain integer / Fraction arithmetic, independent of the model
        # file (site/share-classes-model.py).
        USDC = 1_000_000
        # Two share classes, one vault: A pays 2%, B pays 0.5%. Each
        # class holds 500,000 shares / 500,000 USDC at launch, price 1.00.
        # Alice holds 10,000 shares. All values from
        # site/share-classes-model.py (exact Fractions).
        # 1: year 1, +10% gross. A fee 11,000 -> 539,000, price 539/500 =
        # 1.078; B fee 2,750 -> 547,250, price 2189/2000 = 1.0945. Alice:
        # 10,780 in A vs 10,945 in B, a 165 difference after one year.
        self.assertEqual(550_000 * USDC * 2 // 100, 11_000 * USDC)
        self.assertEqual(550_000 * USDC - 11_000 * USDC, 539_000 * USDC)
        self.assertEqual(Fraction(539_000 * USDC, 500_000),
                         Fraction(539, 500) * USDC)
        self.assertEqual(10_000 * Fraction(539_000 * USDC, 500_000),
                         10_780 * USDC)
        self.assertEqual(550_000 * USDC // 200, 2_750 * USDC)
        self.assertEqual(550_000 * USDC - 2_750 * USDC, 547_250 * USDC)
        self.assertEqual(Fraction(547_250 * USDC, 500_000),
                         Fraction(2189, 2000) * USDC)
        self.assertEqual(10_000 * Fraction(547_250 * USDC, 500_000),
                         10_945 * USDC)
        self.assertEqual(10_945 * USDC - 10_780 * USDC, 165 * USDC)
        # 2: year 2, another +10%. A fee 11,858 -> 581,042, price
        # 290521/250000 = 1.162084; B fee 3,009.875 -> 598,965.125,
        # price 1.19793025. Alice: 11,620.84 vs 11,979.3025, gap 358.4625.
        self.assertEqual(592_900 * USDC * 2 // 100, 11_858 * USDC)
        self.assertEqual(592_900 * USDC - 11_858 * USDC, 581_042 * USDC)
        self.assertEqual(Fraction(581_042 * USDC, 500_000),
                         Fraction(290521, 250000) * USDC)
        self.assertEqual(10_000 * Fraction(581_042 * USDC, 500_000),
                         Fraction(1162084, 100) * USDC)
        self.assertEqual(Fraction(601975, 200) * USDC,
                         Fraction(3009875, 1000) * USDC)
        self.assertEqual(Fraction(601975 * USDC) - Fraction(601975, 200) * USDC,
                         Fraction(4791721, 8) * USDC)
        self.assertEqual(10_000 * Fraction(4791721, 8) * USDC / 500_000,
                         Fraction(119793025, 10000) * USDC)
        self.assertEqual(Fraction(119793025, 10000) * USDC
                         - Fraction(1162084, 100) * USDC,
                         Fraction(28677, 80) * USDC)
        # 3: down year -10% from launch. Both classes still pay: A fee
        # 9,000 -> 441,000, price 0.882; B fee 2,250 -> 447,750, price
        # 0.8955. Alice: 8,820 vs 8,955, a 135 difference in a losing year.
        self.assertEqual(450_000 * USDC * 2 // 100, 9_000 * USDC)
        self.assertEqual(450_000 * USDC - 9_000 * USDC, 441_000 * USDC)
        self.assertEqual(Fraction(441_000 * USDC, 500_000),
                         Fraction(441, 500) * USDC)
        self.assertEqual(10_000 * Fraction(441_000 * USDC, 500_000),
                         8_820 * USDC)
        self.assertEqual(450_000 * USDC // 200, 2_250 * USDC)
        self.assertEqual(450_000 * USDC - 2_250 * USDC, 447_750 * USDC)
        self.assertEqual(Fraction(447_750 * USDC, 500_000),
                         Fraction(1791, 2000) * USDC)
        self.assertEqual(10_000 * Fraction(447_750 * USDC, 500_000),
                         8_955 * USDC)
        self.assertEqual(8_955 * USDC - 8_820 * USDC, 135 * USDC)
        # 4: ten years at +10% a year. A ends near 21,192.76, B near
        # 24,669.35; B/A ratio near 1.164046 -- "only 1.5% a year"
        # compounds to B ending about 16.40% ahead.
        a10 = 10_000 * Fraction(539, 500) ** 10
        b10 = 10_000 * Fraction(2189, 2000) ** 10
        self.assertTrue(21_192 < a10 < 21_193)
        self.assertTrue(24_669 < b10 < 24_670)
        self.assertTrue(3476 < b10 - a10 < 3477)
        self.assertTrue(Fraction(1164, 1000) < b10 / a10
                        < Fraction(1165, 1000))
        # 5: pooled-fee bug. Correct year-1 fees total 13,750; taken from
        # pooled totalAssets and split 50/50, each class loses 6,875, so
        # both sit at 543,125, price 21725/20000 = 1.08625. A gains 4,125
        # against its correct 539,000; B loses 4,125 against its correct
        # 547,250 -- 0.7539% of B's value moves to A in one year.
        self.assertEqual(11_000 * USDC + 2_750 * USDC, 13_750 * USDC)
        self.assertEqual(13_750 * USDC // 2, 6_875 * USDC)
        self.assertEqual(550_000 * USDC - 6_875 * USDC, 543_125 * USDC)
        self.assertEqual(Fraction(543_125 * USDC, 500_000),
                         Fraction(21725, 20000) * USDC)
        self.assertEqual(543_125 * USDC - 539_000 * USDC, 4_125 * USDC)
        self.assertEqual(547_250 * USDC - 543_125 * USDC, 4_125 * USDC)
        self.assertEqual(Fraction(4125, 547250), Fraction(33, 4378))
        # 6: converting A to B at NAV. Alice's 10,000 A shares are worth
        # 10,780 after year 1; at B's price 1.0945 that buys 21,560,000 /
        # 2,189 = 9,849.246... B shares. A stale launch price of 1.00
        # would mint 10,780 B shares: 2,037,420/2,189 = 930.753... shares
        # too many, worth about 1,018.71 USDC.
        conv = Fraction(10_780 * USDC, 1) / (Fraction(2189, 2000) * USDC)
        self.assertEqual(conv, Fraction(21_560_000, 2189))
        self.assertTrue(9849 < conv < 9850)
        over = 10_780 - conv
        self.assertEqual(over, Fraction(2037420, 2189))
        self.assertTrue(930 < over < 931)
        self.assertTrue(1018 < over * Fraction(2189, 2000) < 1019)

    def test_leveraged_vault_guide_numbers(self):
        # Guide #50: leveraged vault -- 100,000 equity / 100,000 shares
        # at 1.00, borrows 100,000 at 5% a year, gross 200,000, 2x.
        # Alice holds 10,000 shares. Re-derived here with plain
        # integer / Fraction arithmetic, independent of the model
        # file (site/leveraged-vault-model.py).
        USDC = 1_000_000
        equity0 = 100_000 * USDC
        debt = 100_000 * USDC
        gross0 = 200_000 * USDC
        supply = 100_000
        alice = 10_000
        rate = Fraction(5, 100)
        # 1: +10% year. Gross 220,000, interest 5,000, equity 115,000,
        # price 23/20 = 1.15, Alice 11,500; unlevered 11,000.
        interest = debt * rate
        self.assertEqual(interest, 5_000 * USDC)
        equity_up = gross0 * Fraction(11, 10) - debt - interest
        self.assertEqual(equity_up, 115_000 * USDC)
        self.assertEqual(Fraction(equity_up, supply), Fraction(23, 20) * USDC)
        self.assertEqual(alice * Fraction(equity_up, supply), 11_500 * USDC)
        self.assertEqual(alice * Fraction(equity_up, supply)
                         - 11_000 * USDC, 500 * USDC)
        # 2: -10% year. Gross 180,000, equity 75,000, price 3/4 = 0.75,
        # Alice 7,500; unlevered 9,000, so 1,500 worse.
        equity_down = gross0 * Fraction(9, 10) - debt - interest
        self.assertEqual(equity_down, 75_000 * USDC)
        self.assertEqual(Fraction(equity_down, supply), Fraction(3, 4) * USDC)
        self.assertEqual(alice * Fraction(equity_down, supply), 7_500 * USDC)
        self.assertEqual(9_000 * USDC
                         - alice * Fraction(equity_down, supply),
                         1_500 * USDC)
        # 3: flat year. Equity 95,000, price 19/20 = 0.95, Alice 9,500.
        # Break-even gross yield is 5,000 / 200,000 = 1/40 = 2.5%.
        equity_flat = gross0 - debt - interest
        self.assertEqual(equity_flat, 95_000 * USDC)
        self.assertEqual(Fraction(equity_flat, supply), Fraction(19, 20) * USDC)
        self.assertEqual(alice * Fraction(equity_flat, supply), 9_500 * USDC)
        self.assertEqual(interest / gross0, Fraction(1, 40))
        # 4: liquidation at 80% LTV. Gross 125,000, a -3/8 = -37.5%
        # fall; equity 25,000, price 1/4, Alice 2,500. At -30% gross
        # 140,000, LTV 5/7, equity 40,000, price 2/5 = 0.40.
        liq_gross = debt / Fraction(4, 5)
        self.assertEqual(liq_gross, 125_000 * USDC)
        self.assertEqual((gross0 - liq_gross) / gross0, Fraction(3, 8))
        self.assertEqual(liq_gross - debt, 25_000 * USDC)
        self.assertEqual(Fraction(liq_gross - debt, supply), Fraction(1, 4) * USDC)
        self.assertEqual(alice * Fraction(liq_gross - debt, supply),
                         2_500 * USDC)
        gross_30 = gross0 * Fraction(7, 10)
        self.assertEqual(Fraction(debt, gross_30), Fraction(5, 7))
        self.assertEqual(Fraction(gross_30 - debt, supply), Fraction(2, 5) * USDC)
        # 5: the accounting bug. Naive price 2.00 vs true 1.00; a
        # 10,000 deposit mints 5,000 shares worth 5,000, losing 5,000.
        self.assertEqual(Fraction(gross0, supply), 2 * USDC)
        self.assertEqual(Fraction(equity0, supply), 1 * USDC)
        shares_naive = Fraction(10_000 * USDC, 1) / Fraction(gross0, supply)
        self.assertEqual(shares_naive, 5_000)
        self.assertEqual(shares_naive * Fraction(equity0, supply),
                         5_000 * USDC)
        # 6: year two. After the up year, gross net of interest is
        # 215,000; +10% -> 236,500, interest 5,000, equity 131,500,
        # price 263/200 = 1.315, Alice 13,150; unlevered 12,100.
        gross1_net = gross0 * Fraction(11, 10) - interest
        self.assertEqual(gross1_net, 215_000 * USDC)
        equity2 = gross1_net * Fraction(11, 10) - interest - debt
        self.assertEqual(equity2, 131_500 * USDC)
        self.assertEqual(Fraction(equity2, supply), Fraction(263, 200) * USDC)
        self.assertEqual(alice * Fraction(equity2, supply), 13_150 * USDC)
        self.assertEqual(alice * Fraction(equity2, supply)
                         - 12_100 * USDC, 1_050 * USDC)
        # Two -10% years: gross 157,500, equity 52,500, price 21/40
        # = 0.525, Alice 5,250; unlevered 8,100, gap 2,850.
        gross_down_net = gross0 * Fraction(9, 10) - interest
        self.assertEqual(gross_down_net, 175_000 * USDC)
        equity2_down = gross_down_net * Fraction(9, 10) - interest - debt
        self.assertEqual(equity2_down, 52_500 * USDC)
        self.assertEqual(Fraction(equity2_down, supply), Fraction(21, 40) * USDC)
        self.assertEqual(alice * Fraction(equity2_down, supply), 5_250 * USDC)
        self.assertEqual(8_100 * USDC
                         - alice * Fraction(equity2_down, supply),
                         2_850 * USDC)

    def test_floor_plus_offset_guide_numbers(self):
        # Guide: floor plus offset -- the two donation defenses
        # together. Attacker seeds with the smallest deposit allowed,
        # donates 1,000,000 USDC, victim deposits 100,000 USDC (and,
        # for the small-victim check, 1,000 USDC), everyone redeems.
        # Re-derived here with plain integer arithmetic, independent
        # of the model file (site/floor-plus-offset-model.py).
        USDC = 1_000_000
        DON = 1_000_000 * USDC
        FLOOR = 100 * USDC
        VIC = 100_000 * USDC
        SMALL = 1_000 * USDC

        def attack(seed, offset, victim_dep):
            V = 10 ** offset
            A, S = 0, 0
            atk_shares = seed * (S + V) // (A + 1)
            A += seed
            S += atk_shares
            A += DON
            vic_shares = victim_dep * (S + V) // (A + 1)
            A += victim_dep
            S += vic_shares
            atk_out = atk_shares * (A + 1) // (S + V)
            A -= atk_out
            S -= atk_shares
            vic_out = vic_shares * (A + 1) // (S + V)
            return victim_dep - vic_out, atk_out - (seed + DON)

        # 1: no defense. Victim loss 909,091 bu = 0.909091 USDC
        # (the checker's no-protection preset), attacker -90,909 bu.
        self.assertEqual(attack(1 * USDC, 0, VIC), (909_091, -90_909))
        # 2: floor alone. Victim loss 1,818 bu = 0.001818 USDC --
        # a 500-fold cut -- attacker -8,182 bu.
        self.assertEqual(attack(FLOOR, 0, VIC), (1_818, -8_182))
        # 3: offset alone. Victim loss 1 bu, attacker -999,999 bu.
        self.assertEqual(attack(1 * USDC, 6, VIC), (1, -999_999))
        # 4: both together. Victim loss exactly 0, attacker only
        # -10,000 bu = -0.010000 USDC -- the floor subsidises the
        # attacker's exit while finishing the victim's protection.
        self.assertEqual(attack(FLOOR, 6, VIC), (0, -10_000))
        # 5: small victim, 1,000 USDC. Floor alone 19 bu, offset
        # alone 1 bu, both together 0; attacker -9,981 / -999,999 /
        # -10,000 bu respectively.
        self.assertEqual(attack(FLOOR, 0, SMALL), (19, -9_981))
        self.assertEqual(attack(1 * USDC, 6, SMALL), (1, -999_999))
        self.assertEqual(attack(FLOOR, 6, SMALL), (0, -10_000))
        # 6: the seed's share count. With offset 6 the 100 USDC seed
        # mints 10**14 shares, 100x the 10**12 of a 1 USDC seed --
        # the bigger seed is what buys the attacker's exit back.
        self.assertEqual(100 * USDC * (0 + 10 ** 6) // 1, 10 ** 14)
        self.assertEqual(1 * USDC * (0 + 10 ** 6) // 1, 10 ** 12)

    def test_pausable_vault_guide_numbers(self):
        # Guide #52: pausable vault -- the pause stops the exits, not
        # the losses. Vault 1,000,000 USDC / 1,000,000 shares, price
        # 1.00; Alice holds 100,000 shares. Re-derived here with plain
        # integer / Fraction arithmetic, independent of the model file
        # (site/pause-vault-model.py).
        USDC = 1_000_000
        # 1: deposits-only pause. Alice redeems 100,000 shares at
        # 1.00 and leaves whole; Bob's deposit reverts, 0 shares.
        self.assertEqual(100_000 * USDC * Fraction(1_000_000 * USDC,
                                                   1_000_000 * USDC),
                         100_000 * USDC)
        self.assertEqual(0, 0)
        # 2: full pause, flat strategy. Alice still exits whole, but
        # the lock costs forgone yield at 10%/yr: 7d = 14,000/73,
        # 30d = 60,000/73, 90d = 180,000/73 USDC.
        self.assertEqual(Fraction(100_000) * Fraction(1, 10)
                         * Fraction(7, 365), Fraction(14_000, 73))
        self.assertEqual(Fraction(100_000) * Fraction(1, 10)
                         * Fraction(30, 365), Fraction(60_000, 73))
        self.assertEqual(Fraction(100_000) * Fraction(1, 10)
                         * Fraction(90, 365), Fraction(180_000, 73))
        self.assertEqual(f"{float(Fraction(14_000, 73)):,.6f}",
                         "191.780822")
        self.assertEqual(f"{float(Fraction(60_000, 73)):,.6f}",
                         "821.917808")
        self.assertEqual(f"{float(Fraction(180_000, 73)):,.6f}",
                         "2,465.753425")
        # 3: full pause + strategy -20%. True price 800,000 /
        # 1,000,000 = 0.80; Alice's 100,000 shares redeem for 80,000,
        # a 20,000 loss the pause locked her into.
        self.assertEqual(Fraction(800_000 * USDC, 1_000_000 * USDC),
                         Fraction(4, 5))
        self.assertEqual(100_000 * USDC * Fraction(4, 5),
                         80_000 * USDC)
        self.assertEqual(100_000 * USDC - 80_000 * USDC,
                         20_000 * USDC)
        # 4: a 1,000,000 USDC donation during the pause, established
        # vault. Price doubles to exactly 2.00; Alice's 100,000
        # shares redeem for 199,999,999,999 base units (one base unit
        # short of 200,000, from the +1 virtual terms), a gain of
        # 99,999,999,999. The next 100,000 USDC depositor after
        # unpause mints 50,000,000,000 base-unit shares and redeems
        # them for 99,999,999,999 -- a loss of one base unit.
        A_don, S0 = 2_000_000 * USDC, 1_000_000 * USDC
        self.assertEqual(Fraction(A_don, S0), 2)
        alice_back = 100_000 * USDC * (A_don + 1) // (S0 + 1)
        self.assertEqual(alice_back, 199_999_999_999)
        self.assertEqual(alice_back - 100_000 * USDC, 99_999_999_999)
        dep = 100_000 * USDC
        new_shares = dep * (S0 + 1) // (A_don + 1)
        self.assertEqual(new_shares, 50_000_000_000)
        A2, S2 = A_don + dep, S0 + new_shares
        new_back = new_shares * (A2 + 1) // (S2 + 1)
        self.assertEqual(new_back, 99_999_999_999)
        self.assertEqual(dep - new_back, 1)
        # 5: contrast -- the same 1,000,000 donation against a NEW
        # vault, attacker first depositor with a 1 USDC seed.
        # Reproduces the checker's no-protection preset exactly:
        # victim loss 909,091 base units (0.909091 USDC), attacker
        # net -90,909 (-0.090909 USDC).
        A, S = 0, 0
        atk_in = 1 * USDC
        atk_shares = atk_in * (S + 1) // (A + 1)
        A += atk_in
        S += atk_shares
        A += 1_000_000 * USDC
        vic_shares = dep * (S + 1) // (A + 1)
        A += dep
        S += vic_shares
        atk_out = atk_shares * (A + 1) // (S + 1)
        A -= atk_out
        S -= atk_shares
        vic_out = vic_shares * (A + 1) // (S + 1)
        self.assertEqual(dep - vic_out, 909_091)
        self.assertEqual(atk_out - (atk_in + 1_000_000 * USDC),
                         -90_909)

    def test_donation_loss_chart(self):
        # The donation table shows four losses that are not monotonic in
        # the donation (1B loses less than 1M) — easy to miss in a column
        # of decimals. The bar chart under the table makes the shape
        # visible: bars scaled to the worst row, red where the row breaches
        # the pass bound. The chart adds no new numbers; every figure is
        # the model's own, and the bar widths are pinned here. A row whose
        # bar would be under 0.5% of the worst row is omitted from the
        # chart entirely — the table above still lists it with its exact
        # figure — and when fewer than two rows can draw a bar there is
        # no chart at all, just one sentence carrying the same numbers
        # (visual verdict #94: placeholder rows reading as a broken
        # chart were the whole site's ugliest element; a grey fill, a
        # log scale and a minimum width were already ruled out by
        # verdicts #59/#72 and the scale rule, so not drawing is the
        # remaining honest move). The scale stays linear to the worst
        # row (no log scale, no minimum width). Bars are 1.7em tall
        # with tight rows, so the chart reads as a chart rather than
        # four hairlines in a mostly blank box (verdict #59).
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        # No protection: losses 0 / 6 / 909091 / 99890 base units.
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("loss-chart", html)
        # The checker chart carries no grey fill: a partial bar used to
        # trail a light-grey remainder — the track's presence was
        # inconsistent, reading as a half-empty bar. Bars now sit
        # inside the same hairline frame every row carries
        # (verdict #51); width alone carries the scale. Verdict #95
        # residual: that 1px #6b7280 frame made the ~89% unfilled
        # remainder of a short bar read as an empty placeholder box,
        # so the frame is gone too — the fill alone shows, against
        # the white card, with the note stating the scale.
        self.assertIn("loss-chart loss-chart--bare", html)
        self.assertIn(".loss-chart--bare .loss-track{position:relative;"
                      "grid-column:2;background:transparent;border:0}",
                      build.CSS)
        # Visual verdict #136 (2026-11-21): the legend names the
        # axis maximum now, not the worst row as the scale — the
        # worst row's value is still named, as the axis reference.
        self.assertIn("Axis 0–1 USDC (worst row 0.909091 USDC)", html)
        self.assertEqual(html.count("loss-fill fail"), 2)
        self.assertEqual(html.count("loss-fill pass"), 0)
        # The two small rows (0 and 0.000006 USDC) would draw a 0.0%
        # fill, so they are omitted from the chart entirely — no bar,
        # no placeholder slot (verdict #94: the placeholder rows were
        # the site's ugliest element). The note names them, and the
        # table above still lists both with exact figures.
        self.assertEqual(html.count("loss-track--empty"), 0)
        self.assertEqual(html.count("loss-too-small"), 0)
        self.assertEqual(html.count("loss-track--tiny"), 0)
        self.assertNotIn("too small to draw", html)
        self.assertIn("Rows under 0.5% of the worst row (1 USDC, 1,000 USDC) — see the table.", html)
        # Visual verdict #114 new finding (d): the chart legend lived
        # in two places — the omitted-rows header above the bars and
        # the scale/red footnote below them. It is now one block.
        # Visual verdict #139 (2026-11-21): that one block moved
        # below the axis — the title sits directly above the bars,
        # and the legend reads as the chart's key, not its preamble.
        # There is still no footnote below the chart at all.
        # Visual verdict #116 new finding (c): the legend is a list
        # now — one line per idea, each with a bold label — not one
        # paragraph of four sentences.
        self.assertIn("<ul class='loss-head'><li><strong>Not drawn:</strong> Rows under 0.5% of the worst row (1 USDC, 1,000 USDC) — see the table.</li><li><strong>Scale:</strong> Axis 0–1 USDC (worst row 0.909091 USDC); gridlines at 25%, 50%, 75%.</li><li><strong>Red bars:</strong> breach the pass bound.</li></ul>", html)
        self.assertNotIn("<p class='loss-head'>", html)
        self.assertLess(html.index("loss-title"), html.index("loss-row"))
        self.assertLess(html.index("loss-axis"), html.index("loss-head"))
        self.assertNotIn("<p class='loss-note'>", html)
        self.assertIn(".loss-head{font-size:.92em;color:#374151;margin:0 0 .5em;padding-left:1.2em}", build.CSS)
        self.assertIn(".loss-head li{margin:.15em 0}", build.CSS)
        # The Worker-side template renders the same omission note, and
        # no placeholder label anywhere. The note is built conditionally
        # now (visual verdict #130): the reference is the pass bound
        # on a bound-scaled chart, the worst row otherwise — both
        # branches must be present in the template.
        self.assertIn("Rows under 0.5% of \"+(boundScale?"
                      "\"the pass bound\":\"the worst row\")+\" (",
                      build.checker_results_html_js())
        self.assertIn("loss-head", build.checker_results_html_js())
        self.assertNotIn("too small to draw", build.checker_results_html_js())
        self.assertNotIn("loss-track--tiny", build.checker_results_html_js())
        # Visual verdict #136 (2026-11-21): bars are drawn against
        # the 0–1 USDC axis now — worst bar 90.9%, 1B bar 10.0%.
        self.assertIn("width:90.9%", html)
        self.assertIn("width:10.0%", html)
        self.assertIn("0.909091", html)
        # Seeded vault: losses [1, 1, 1, 13] — all within bound, all green.
        # Visual verdict #137 (2026-11-21): nothing breaches, so no
        # chart is drawn at all — the sentence carries the worst loss
        # (13 base units, 1.3% of the bound) instead of four green
        # bars against a 20-unit axis.
        A50 = 50_000_000_000_000
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                    vault_assets=A50, vault_supply=A50),
            vic=100_000_000_000, off=0, mn=0, fee=0, vassets=A50, vshares=A50)
        self.assertNotIn("loss-chart", html)
        self.assertEqual(html.count("loss-fill"), 0)
        self.assertIn("<ul class='loss-head'><li><strong>Within the bound:</strong> No donation breaches the pass bound, so there is no chart to draw — the worst victim loss is 0.000013 USDC, 1.3% of the 0.001 USDC pass bound.</li></ul>", html)
        # Offset 18: every loss is 0 — no row can draw a bar, so there
        # is no chart at all, just the one legend item (verdict #94:
        # four placeholder rows were the worst case of the broken-chart
        # read; verdict #117 (f): the zero-loss facts use the same
        # legend list form as the charted preset, not a grey
        # footnote). The item carries the exact figure.
        html = build.results_html(
            run_all(Vault(decimals_offset=18, min_deposit=1_000_000,
                          perf_fee_bps=1000)))
        self.assertNotIn("loss-chart", html)
        self.assertEqual(html.count("width:0.0%"), 0)
        self.assertEqual(html.count("loss-track--empty"), 0)
        self.assertEqual(html.count("loss-too-small"), 0)
        self.assertIn("<ul class='loss-head'><li><strong>No loss:</strong> No donation loses anything, so there is no chart to draw — every victim loss is 0.000000 USDC.</li></ul>", html)
        self.assertNotIn("<p class='loss-note'>", html)
        # Mixed table: one tiny row, one drawable row, one error row —
        # a single drawable bar IS a chart now (visual verdict #123,
        # 2026-11-20): the default ALL PASS preset's sentence-only
        # form read as a missing chart, a blank area after the table.
        # The one bar shows the peak at its true linear scale (100% =
        # worst row); the tiny row is named in the legend, the error
        # row is named in it and explained in the table's Note column.
        # No empty placeholder slot returns (verdict #94).
        mixed = [{"name": "donation_inflation", "pass": False, "detail": [
            {"donation": 1_000_000_000, "victim_loss": 6,
             "attacker_net": -1},
            {"donation": 1_000_000_000_000, "victim_loss": 909091,
             "attacker_net": -90909},
            {"donation": 1_000_000_000_000_000, "victim_loss": None,
             "attacker_net": None, "error": "below minimum deposit"}]}]
        html = build.results_html(mixed, vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("loss-chart loss-chart--bare", html)
        self.assertEqual(html.count("loss-fill fail"), 1)
        self.assertEqual(html.count("loss-row"), 1)
        self.assertIn("width:90.9%", html)
        self.assertEqual(html.count("loss-track--empty"), 0)
        self.assertEqual(html.count("loss-too-small"), 0)
        self.assertIn("<ul class='loss-head'><li><strong>Not drawn:</strong> Rows under 0.5% of the worst row (1,000 USDC) — see the table.</li><li><strong>No figure:</strong> Rows with no loss figure are not drawn either — see the table.</li><li><strong>Scale:</strong> Axis 0–1 USDC (worst row 0.909091 USDC); gridlines at 25%, 50%, 75%.</li><li><strong>Red bars:</strong> breach the pass bound.</li></ul>", html)
        self.assertNotIn("Victim loss peaks at", html)
        self.assertNotIn("too little to draw", html)
        self.assertNotIn("<p class='loss-note'>", html)
        # Chart with an error row as well as an omitted row: both
        # sentences join the header, in the same order, followed by
        # the scale/red sentence; no footnote below the chart.
        mixed2 = [{"name": "donation_inflation", "pass": False, "detail": [
            {"donation": 1_000_000, "victim_loss": 6,
             "attacker_net": -1},
            {"donation": 1_000_000_000, "victim_loss": 909091,
             "attacker_net": -90909},
            {"donation": 1_000_000_000_000, "victim_loss": 500000,
             "attacker_net": -1},
            {"donation": 1_000_000_000_000_000, "victim_loss": None,
             "attacker_net": None, "error": "below minimum deposit"}]}]
        html = build.results_html(mixed2, vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("loss-chart loss-chart--bare", html)
        self.assertIn("<ul class='loss-head'><li><strong>Not drawn:</strong> Rows under 0.5% of the worst row (1 USDC) — see the table.</li><li><strong>No figure:</strong> Rows with no loss figure are not drawn either — see the table.</li><li><strong>Scale:</strong> Axis 0–1 USDC (worst row 0.909091 USDC); gridlines at 25%, 50%, 75%.</li><li><strong>Red bars:</strong> breach the pass bound.</li></ul>", html)
        # Visual verdict #139 (2026-11-21): the legend follows the
        # axis now — title, bars, axis, then the key.
        self.assertLess(html.index("loss-title"), html.index("loss-row"))
        self.assertLess(html.index("loss-axis"), html.index("loss-head"))
        self.assertNotIn("<p class='loss-note'>", html)
        # Giant minimum deposit: every row errors, no number to chart.
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=10 ** 21,
                          perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=10 ** 21, fee=0)
        self.assertNotIn("loss-chart", html)

    def test_loss_chart_values_under_label_in_key_column(self):
        # Visual verdict #110 item 2 (2026-11-19): on
        # /checker/?preset=noprot the two values sat ~660px apart in
        # different colours — 0.909091 white inside the 100% bar,
        # 0.099890 dark outside the 11% bar (the verdict #96 hug-the-
        # bar-end design) — and the eye had to jump to find them.
        # Visual verdict #172 (2026-11-24): the three-column grid
        # retired — the label + value zone took ~48% of the chart,
        # so the 10% bar sat beside ~400px of text. Values now sit
        # under their donation label in the key column, both lines
        # right-aligned to the same track edge: one x for every row,
        # one colour, each adjacent to its bar's start. This is not
        # a return to #96's fixed right-hand column (orphaned ~630px
        # from a short bar's end); the value is adjacent to its bar.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        # Full row: key (label over value), track — in that order,
        # value dark.
        # Visual verdict #106 (noprot item 1): a breaching row also
        # carries how many times its loss exceeds the pass bound, so
        # the short red bar is not misread as a small loss — the worst
        # row is 909091/1000 = 909x, the 1B row 99890/1000 = 99.9x.
        # Visual verdict #123 new finding ③ (2026-11-20): the label
        # carries its unit and the multiple's referent inline, so it
        # no longer duplicates the table's bare number.
        self.assertIn("<div class='loss-row'><span class='loss-key'>"
                      "<span class='loss-label'>"
                      "1,000,000 USDC</span><span class='loss-value'>"
                      "0.909091 USDC &middot; 909&times; the bound</span></span>"
                      "<span class='loss-track'><span class='loss-fill fail' "
                      "style='width:90.9%'></span></span></div>", html)
        # Short bar: same value position, same colour, no --pct.
        self.assertIn("<div class='loss-row'><span class='loss-key'>"
                      "<span class='loss-label'>"
                      "1,000,000,000 USDC</span><span class='loss-value'>"
                      "0.099890 USDC &middot; 99.9&times; the bound</span></span>"
                      "<span class='loss-track'><span class='loss-fill fail' "
                      "style='width:10.0%'></span></span></div>", html)
        # Visual verdict #124 new finding ③ (2026-11-20): the
        # legend no longer carries a ×N line — the bar value itself
        # says "909× the bound", so the legend line restated it.
        # The multiple's meaning is defined by the label, not the
        # legend any more.
        self.assertNotIn("<strong>×N:</strong>", html)
        self.assertNotIn("The ×N after a red value", html)
        # Visual verdict #123 new finding ③ follow-up (2026-11-20):
        # the longer label squeezes the mobile track to ~30px, so
        # below 640px the bare-chart value takes its own line and
        # the track gets the full row width again. The key wrapper
        # is the grid item on mobile too, left-aligned like the
        # label and value always were below 640px.
        self.assertIn(".loss-chart--bare .loss-key,.loss-chart--bare "
                      ".loss-track,.loss-chart--bare .loss-axis"
                      "{grid-column:1}",
                      build.CSS)
        self.assertIn(".loss-chart--bare .loss-key .loss-label,"
                      ".loss-chart--bare .loss-key .loss-value"
                      "{text-align:left}",
                      build.CSS)
        # No trace of the hug-the-bar-end mechanism: no inside class,
        # no --pct variable anywhere in the chart markup or CSS.
        self.assertNotIn("loss-value--inside", html)
        self.assertNotIn("--pct:", html)
        self.assertNotIn("loss-value--inside", build.CSS)
        self.assertNotIn("--pct", build.CSS)
        # The CSS pins the new positioning: the value is a block
        # line inside the key column, dark text, never absolutely
        # positioned — and it is no longer a grid item of its own.
        self.assertIn(".loss-chart--bare .loss-key .loss-value"
                      "{white-space:nowrap;color:#111827}",
                      build.CSS)
        self.assertNotIn(".loss-chart--bare .loss-value{grid-column:2",
                         build.CSS)
        # 2026-11-19 gridlines (verdict #120 item 3): position:relative
        # is back on the bare track, but for a different job — it
        # anchors the gridline ::after overlay, not an absolutely
        # positioned value. The value stays static (asserted above);
        # the overlay is pinned by test_loss_chart_gridlines.
        self.assertIn(".loss-chart--bare .loss-track{position:relative;"
                      "grid-column:2;background:transparent;border:0}",
                      build.CSS)
        # Guide charts (plain .loss-chart, values as flex items) are
        # untouched: the new rule is scoped to --bare only.
        self.assertNotIn(".loss-chart .loss-value{position:absolute",
                         build.CSS)
        # The Worker-side template renders the same structure.
        js = build.checker_results_html_js()
        self.assertNotIn("loss-value--inside", js)
        self.assertNotIn("--pct:", js)
        self.assertNotIn("pct>=60", js)
        self.assertIn("<span class='loss-value'>", js)
        # Worker-side multiple: same rule as the Python renderer.
        self.assertIn("&middot;", js)
        self.assertIn("&times;", js)
        self.assertIn("boundB", js)
        # Short-bar case: seeded vault, losses [1, 1, 1, 13] — nothing
        # breaches, so no chart is drawn at all (visual verdict #137,
        # 2026-11-21) and there are no bar values to position; the
        # sentence carries the worst loss instead. The value-position
        # rule above is still tested on the noprot chart.
        A50 = 50_000_000_000_000
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                    vault_assets=A50, vault_supply=A50),
            vic=100_000_000_000, off=0, mn=0, fee=0, vassets=A50, vshares=A50)
        self.assertEqual(html.count("loss-value--inside"), 0)
        self.assertEqual(html.count("<span class='loss-value'>"), 0)
        self.assertNotIn("loss-chart", html)
        self.assertIn("the worst victim loss is 0.000013 USDC, 1.3% of the 0.001 USDC pass bound.", html)
        self.assertNotIn("--pct:", html)

    def test_loss_chart_passing_rows_carry_bound_share(self):
        # Visual verdict #128 item 2 follow-up (2026-11-20,
        # checker-improvement): the headless re-check found the
        # verdict's literal claim false — the default ALL PASS chart
        # DOES draw its one bar (full-width dark green, 100% of the
        # worst row, verified at 1919px and 360px in Worker render,
        # static page and live curl) — but the bar's length is a
        # tautology: the worst row is 100% of itself, so the chart
        # says nothing the table does not already say. The breaching
        # rows already carry their meaning inline ("909x the bound");
        # a passing row now carries its share of the pass bound
        # whenever that share is >= 1%: the default preset's worst
        # row reads "0.000900 USDC · 90% of the bound" — even the
        # worst case is a tenth short of failing. The 1% floor keeps
        # tiny passing rows plain (noprot's 0 and 0.000006 would read
        # "0.0006% of the bound", noise), and passing means loss <=
        # bound, so the share never exceeds 100%.
        # Visual verdict #130 (2026-11-20, checker-improvement): the
        # bar length now agrees with the label — nothing breaches and
        # the worst loss is 90% of the bound, so the chart is scaled
        # to the bound and the bar is 90% wide instead of 100% of
        # itself.
        # Visual verdict #137 (2026-11-21): the default preset draws
        # no chart at all any more — the sentence carries the worst
        # loss and its share of the bound instead. The bar-label rule
        # below is still tested, on a synthetic breaching chart where
        # a passing row is drawable next to a breaching one.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        # Default AlphaPrimer preset: nothing breaches, so no chart is
        # drawn (visual verdict #137, 2026-11-21) — the sentence
        # carries the worst loss and its share of the bound instead
        # of the one green bar.
        html = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertNotIn("loss-chart", html)
        self.assertIn("<ul class='loss-head'><li><strong>Within the bound:</strong> No donation breaches the pass bound, so there is no chart to draw — the worst victim loss is 0.000900 USDC, 90% of the 0.001 USDC pass bound.</li></ul>", html)
        # The bar-label rule itself still lives on breaching charts: a
        # passing drawable row next to a breaching one carries its
        # share of the bound ("90% of the bound"), not a bare number.
        # Losses 900 / 100000 base units: the 900 row is 0.9% of the
        # worst row (drawable) and 90% of the bound (passing); the
        # 100000 row breaches at 100x the bound.
        mixed_share = [{"name": "donation_inflation", "pass": False, "detail": [
            {"donation": 1_000_000_000, "victim_loss": 900,
             "attacker_net": -1},
            {"donation": 1_000_000_000_000, "victim_loss": 100000,
             "attacker_net": -1}]}]
        html = build.results_html(mixed_share, vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("<div class='loss-row'><span class='loss-key'>"
                      "<span class='loss-label'>"
                      "1,000 USDC</span><span class='loss-value'>"
                      "0.000900 USDC &middot; 90% of the bound</span></span>"
                      "<span class='loss-track'><span class='loss-fill pass' "
                      "style='width:0.9%'></span></span></div>", html)
        self.assertIn("0.100000 USDC &middot; 100&times; the bound", html)
        # Noprot: breaching multiples intact, no bound share anywhere
        # (the two tiny passing rows are not drawn at all).
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("0.909091 USDC &middot; 909&times; the bound", html)
        self.assertEqual(html.count("% of the bound"), 0)
        # Offset 18: no loss anywhere, no chart, no bound share.
        html = build.results_html(
            run_all(Vault(decimals_offset=18, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=18, mn=1_000_000, fee=1000)
        self.assertNotIn("of the bound</span>", html)
        self.assertIn("No loss:", html)
        # The Worker-side template renders the same rule.
        js = build.checker_results_html_js()
        self.assertIn("% of the bound", js)
        # Format guard: 99.5%+ never rounds up to "100%" unless the
        # loss is exactly at the bound.
        self.assertIn("Math.min(pctB,99.9)", js)

    def test_loss_chart_gridlines(self):
        # Visual verdict #120 checker item 3 (2026-11-19): the donation
        # chart had no axis — the 11% bar could only be read via the
        # legend. Gridlines at 25/50/75% of the scale (worst row),
        # drawn as a ::after overlay. The overlay is positioned, so
        # the track carries position:relative again — for the overlay
        # only; the value stays static in the key column (see the
        # #110/#172 test above), never absolutely positioned inside
        # the track.
        # Visual verdict #121 item 4 (2026-11-19): alpha .25 was too
        # faint — measured luminance delta ~17 on a red fill, ~58 on
        # the white track — so the lines are darkened to .5 here.
        # Visual verdict #122 item 1 (2026-11-20): at .5 the 1px
        # lines were clear on the red fill but still easy to miss on
        # the white track at normal viewing distance, so the lines
        # are widened to 2px here (alpha stays .5).
        # Visual verdict #123 item (a) (2026-11-20): at .5 the 2px
        # lines were still faint on the white track at normal viewing
        # distance — only clearly visible zoomed 3x — while the
        # red-bar lines already read black and clear. Width alone
        # did not fix noticeability, so alpha goes .5 -> .8 here;
        # the red-bar lines go near-black, which is their already
        # accepted look, not a regression.
        # Visual verdict #140 item 2 (2026-11-21, REVERSED by #189
        # 2026-11-24): #120 drew the lines ABOVE the fills so they
        # stayed visible across a 100% bar — and the near-black
        # lines cut every long red bar into segments, so #140 put
        # the lines BEHIND the fills (fill z-index:1 over the
        # z-index:auto ::after). Two later real-browser verdicts
        # (#177, #189) read the result the other way: with 26.6px
        # bars and 8.5px gaps the only visible fragments are the
        # stubs in the gaps, which read as stray ticks, not a grid.
        # The ::after now carries z-index:2, so the lines run
        # continuously across the bars. Alpha and width are
        # untouched (.8, 2px) — lightening them would reopen
        # #121–#123.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        self.assertIn(".loss-chart--bare .loss-track{position:relative;"
                      "grid-column:2;background:transparent;border:0}",
                      build.CSS)
        # The fill keeps its positioning (z-index:1), but the
        # gridlines now sit above it: the ::after carries
        # z-index:2 (pinned in full below), which beats the fill's
        # 1. Scoped to --bare: guide charts have no gridlines, so
        # their fills stay unpositioned.
        self.assertIn(".loss-chart--bare .loss-fill{position:relative;"
                      "z-index:1}", build.CSS)
        self.assertNotIn(".loss-chart .loss-fill{position:relative",
                         build.CSS)
        self.assertIn(
            ".loss-chart--bare .loss-track::after{content:\"\";"
            "position:absolute;inset:-1.15em 0;z-index:2;"
            "pointer-events:none;"
            "background-image:linear-gradient(to right,transparent "
            "calc(25% - 1px),rgba(17,24,39,.8) calc(25% - 1px),"
            "rgba(17,24,39,.8) calc(25% + 1px),transparent "
            "calc(25% + 1px)),linear-gradient(to right,transparent "
            "calc(50% - 1px),rgba(17,24,39,.8) calc(50% - 1px),"
            "rgba(17,24,39,.8) calc(50% + 1px),transparent "
            "calc(50% + 1px)),linear-gradient(to right,transparent "
            "calc(75% - 1px),rgba(17,24,39,.8) calc(75% - 1px),"
            "rgba(17,24,39,.8) calc(75% + 1px),transparent "
            "calc(75% + 1px))}",
            build.CSS)
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        # The legend Scale line says what the lines mark — the axis
        # maximum on a breaching chart (visual verdict #136), the
        # pass bound on a bound-scaled one.
        self.assertIn("gridlines at 25%, 50%, 75%.",
                      html)
        # Worker-side template carries both sentences (one per scale
        # branch).
        self.assertIn("gridlines at 25%, 50%, 75%.",
                      build.checker_results_html_js())
        self.assertIn("gridlines at 25%, 50%, 75%.",
                      build.checker_results_html_js())
        # Guide charts (plain .loss-chart) get no gridlines: the rule
        # is scoped to --bare only.
        self.assertNotIn(".loss-chart .loss-track::after", build.CSS)
        # Visual verdict #160 item (4) (2026-11-23,
        # checker-improvement): the over-fill ::before seam is
        # GONE. #157 added it so the gridlines read as one
        # continuous line; #159 cut it .35 -> .12 when the live
        # browser read it as cracks; #160 still read cracks, so
        # a third alpha cut is not the lever — no seam over a bar
        # at any alpha.
        # Visual verdict #189 (2026-11-24, checker-improvement):
        # the gridlines now cross the fills instead of living
        # under them (see the #140 reversal above), and the
        # ::after extends 1.15em each side of the track so the
        # lines run down the chart across bars and gaps alike.
        # The .325em extension assumed single-line rows; #172's
        # two-line key made each row 52px tall (inter-track gap
        # 33.5px), so .325em left a ~23px white band mid-gap.
        # The bare track drops overflow:hidden for the extension
        # to paint, and the fill carries the 3px corner radius
        # itself. Mobile pulls the extension back to .15em (half
        # the .3em gap) so it cannot poke into the stacked
        # label/value rows.
        self.assertNotIn(".loss-chart--bare .loss-track::before",
                         build.CSS)
        self.assertNotIn(".loss-chart .loss-track::before", build.CSS)
        self.assertIn(".loss-chart--bare .loss-track{overflow:visible}",
                      build.CSS)
        self.assertIn(".loss-chart--bare .loss-fill{border-radius:3px}",
                      build.CSS)
        self.assertIn(
            ".loss-chart--bare .loss-track::after{inset:-.15em 0}",
            build.CSS)
        # Visual verdict #163 item 1 (2026-11-24,
        # checker-improvement): the ::after extends .2em above every
        # track, so the first row's gridlines poked ~3px above the top
        # bar — three 2px stubs floating between the peak line and the
        # first bar (pixel-measured 1543-1545 against bar top 1546).
        # The first row's ::after is capped at top:0; the bottom
        # extension stays, so the lines still run down to the axis
        # and the inter-row seams keep bridging.
        self.assertIn(
            ".loss-chart--bare .loss-row:first-of-type "
            ".loss-track::after{top:0}",
            build.CSS)
        # The selector's premise: the title and the peak line are
        # <p>, so the first <div> child of the chart is the first
        # row — :first-of-type can only match a row. Only the
        # chart's own opening <div> precedes the first row.
        chart = html[html.index("<div class='loss-chart "
                                 "loss-chart--bare'>"):]
        seg = chart[:chart.index("<div class='loss-row'>")]
        self.assertEqual(seg.count("<div"), 1)
        self.assertIn("<p class='loss-title'>", html)
        # Same premise in the Worker-side template: title and peak
        # are <p>, rows are <div>.
        js = build.checker_results_html_js()
        self.assertIn("c+=\"<p class='loss-title'>", js)
        self.assertIn("c+=\"<div class='loss-row'>", js)

    def test_verdict189_gridlines_cross_bars(self):
        # Visual verdict #189 (2026-11-24, checker-improvement):
        # two real-browser verdicts (#177, #189) read the
        # behind-bars gridlines as stray ticks — with 26.6px bars
        # and 8.5px gaps only the stubs in the gaps showed. The
        # ::after now sits ABOVE the fills (z-index:2 beats the
        # fill's z-index:1, reversing #140), and its desktop
        # extension grows .325em -> 1.15em so the lines bridge the
        # 33.5px inter-track gap #172's two-line key leaves
        # (pixel-measured, hidden_files/measure-verdict189.py:
        # pitch 60.1px, key 51.6px, track font 15.64px; needed
        # 16.8px = 1.07em per side). Mobile keeps -.15em (stacked
        # rows) and the #164 first-row cap (top:0) still holds.
        # Render-time only: the model, the numbers and the API
        # JSON are untouched.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        after = re.search(
            r"\.loss-chart--bare \.loss-track::after\{[^}]*\}",
            build.CSS)
        self.assertIsNotNone(after)
        self.assertIn("z-index:2", after.group(0))
        self.assertIn("inset:-1.15em 0", after.group(0))
        self.assertIn("rgba(17,24,39,.8)", after.group(0))
        # The fill keeps its own z-index:1 — the ::after's 2 is
        # what wins, not the fill losing its positioning.
        self.assertIn(".loss-chart--bare .loss-fill{position:relative;"
                      "z-index:1}", build.CSS)
        # First-row cap and mobile pull-back are unchanged.
        self.assertIn(
            ".loss-chart--bare .loss-row:first-of-type "
            ".loss-track::after{top:0}",
            build.CSS)
        self.assertIn(
            ".loss-chart--bare .loss-track::after{inset:-.15em 0}",
            build.CSS)
        # Guide charts (plain .loss-chart) get no gridlines.
        self.assertNotIn(".loss-chart .loss-track::after", build.CSS)

