    def test_rounding_sentence_renders_without_table(self):
        # Visual verdict #158 (2026-11-23, checker-improvement):
        # the rounding card's single sentence ("floor/ceil directions
        # hold") rendered as a full-width bordered table — a ~950px
        # box holding a ~200px sentence, the ugliest thing on the
        # site. It now renders as a plain paragraph inside the
        # slate-accent details block; the other four non-donation
        # cards keep their tables. Render-only: the model string,
        # the splitter and the API JSON are untouched.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            self.assertIn("<p class='check-sentence'>floor/ceil "
                          "directions hold</p>", html)
            self.assertNotIn("<td class='check-sentence'", html)
            self.assertEqual(html.count("<table class='check-table'>"), 4)
            # The rounding card keeps its title, blurb, pass rule
            # and guide link — only the table box is gone.
            self.assertIn("Rounding directions", html)
            self.assertIn("/guides/erc4626-rounding-errors/", html)
            self.assertIn("<strong>Pass rule:</strong> Every preview "
                          "within 1 base unit", html)
            # Numbers untouched by a render-only change.
            self.assertIn("0.909091" if v.decimals_offset == 0
                          else "0.000900", html)
        # Worker-side template: same paragraph branch.
        js = build.checker_results_html_js()
        self.assertIn("<p class='check-sentence'>", js)
        self.assertIn("r.detail.every(function(line){return "
                      "!splitDetailLine(line);})", js)

    def test_split_detail_line(self):
        # The render-time splitter behind the check-table: every model
        # detail-line shape maps to (label, value) rows, or None for a
        # line with no splittable figure. The model strings are the
        # contract — the splitter must not invent or drop a figure.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        NB = "\u00a0"
        self.assertEqual(
            build.split_detail_line(
                f"smallest deposit minting 1 share: 0.000001{NB}USDC"),
            [("smallest deposit minting 1 share", f"0.000001{NB}USDC")])
        self.assertEqual(
            build.split_detail_line(
                f"deposit preview matches execution: 10,000,000,000,000,000{NB}shares"),
            [("deposit preview matches execution",
              f"10,000,000,000,000,000{NB}shares")])
        self.assertEqual(
            build.split_detail_line(
                f"1{NB}USDC mints 1,000,000,000,000{NB}shares"),
            [("1" + NB + "USDC mints", f"1,000,000,000,000{NB}shares")])
        self.assertEqual(
            build.split_detail_line(
                f"1{NB}USDC buys 1,000,000,000,000{NB}shares (unchanged)"),
            [(f"1{NB}USDC buys",
              f"1,000,000,000,000{NB}shares (unchanged)")])
        self.assertEqual(
            build.split_detail_line(
                f"1{NB}USDC buys 1,000,000,000,000{NB}shares -> "
                f"999,999,999,999{NB}shares"),
            [(f"1{NB}USDC buys",
              f"1,000,000,000,000{NB}shares -> 999,999,999,999{NB}shares")])
        self.assertEqual(
            build.split_detail_line(
                f"yield 10,000.000000{NB}USDC, fee 1,000.000000{NB}USDC, "
                f"holder gain 9,000.000000{NB}USDC"),
            [("Yield", f"10,000.000000{NB}USDC"),
             ("Fee", f"1,000.000000{NB}USDC"),
             ("Holder gain", f"9,000.000000{NB}USDC")])
        self.assertEqual(
            build.split_detail_line(
                f"deposit 10,000,000,000,000,000{NB}shares == "
                f"10,000,000,000,000,001{NB}shares"),
            [("deposit", f"10,000,000,000,000,000{NB}shares == "
                         f"10,000,000,000,000,001{NB}shares")])
        self.assertEqual(
            build.split_detail_line(
                f"min-deposit floor binds: effective minimum 1.000000{NB}USDC"),
            [("min-deposit floor binds", f"1.000000{NB}USDC")])
        self.assertIsNone(
            build.split_detail_line("floor/ceil directions hold"))
        self.assertIsNone(
            build.split_detail_line("deposit rounding off for 1000000"))
        # The splitter is total over the live model: every string
        # detail line of both presets splits or falls back to a
        # sentence row — never an exception, never a dropped line.
        for v in (Vault(decimals_offset=6, min_deposit=1_000_000,
                        perf_fee_bps=1000),
                  Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)):
            for r in run_all(v):
                for line in r["detail"]:
                    if isinstance(line, str):
                        build.split_detail_line(line)
                        build.detail_table([line])

    def test_check_table_short_labels(self):
        # Visual verdict #130 (secondary item, headless-measured
        # 2026-11-20): four detail labels wrapped with an orphaned
        # last word at 320-700px — the preview labels ended
        # "...matches / execution", the minimum-deposit label ended
        # "...minting 1 / share" — because the labels are long enough
        # to wrap on their own at a ~138px label column (the value
        # column's longest token used to be the 26-char
        # "10,000,000,000,000,000 shares"; visual verdict #174
        # compacts it to "10Q shares" at render time, but the label
        # shortening stays). The displayed labels shorten at render
        # time; the model strings, the splitter and the API JSON keep
        # the full wording (pinned by test_split_detail_line and by
        # the "preview matches execution" model assertion above).
        # The share-price label is not in this map: visual verdict
        # #174 restated the line as "1 USDC buys N shares", whose
        # label is short already and needs no shortening.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        short = {
            "deposit preview matches execution": "deposit",
            "mint preview matches execution": "mint",
            "redeem preview matches execution": "redeem",
            "smallest deposit minting 1 share": "1-share threshold",
            # Visual verdict #159 item (a): the Minimum label
            # "min-deposit floor binds" orphaned "binds" and the
            # "no zero-share deposit" label wrapped too, both at
            # 1919px on the default preset. The preview labels
            # shorten one step further — the card title, blurb and
            # Pass rule all say "preview" already.
            "no zero-share deposit": "no zero-share",
        }
        # "min-deposit floor binds" only exists on the default preset
        # (noprot's min_deposit is 0, so the floor never binds) —
        # check it on the default HTML only; the JS map carries it
        # regardless, so the template assertion below covers both.
        short_default_only = {"min-deposit floor binds": "floor binds"}
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            for long_label, short_label in short.items():
                self.assertIn(
                    f"<td class='check-label'>{short_label}</td>", html)
                self.assertNotIn(f"{long_label}</td>", html)
            if v.decimals_offset == 6:
                for long_label, short_label in short_default_only.items():
                    self.assertIn(
                        f"<td class='check-label'>{short_label}</td>", html)
                    self.assertNotIn(f"{long_label}</td>", html)
        # The Worker-side template carries the same map and applies
        # it to the label cell, not the value cell.
        js = build.checker_results_html_js()
        self.assertIn("function shortLabel(s)", js)
        for long_label, short_label in {**short, **short_default_only}.items():
            self.assertIn(f'"{long_label}":"{short_label}"', js)
        self.assertIn("nbspUnits(esc(shortLabel(row[0])))", js)
        self.assertNotIn("shortLabel(row[1])", js)

    def test_verdict174_share_counts_are_compact(self):
        # Visual verdict #174 (2026-11-24, checker-improvement):
        # the default page showed "1 USDC mints 1,000,000,000,000
        # shares" and "deposit preview matches execution:
        # 10,000,000,000,000,000 shares" — exact, but a first-time
        # vault developer cannot read a 13- or 20-digit run, and at
        # offset 18 the counts reach 25 digits. Render-time only:
        # the model strings, the splitter and the API JSON keep the
        # exact integers; only the displayed value compacts, and
        # only when the compact form is exact — never rounded. The
        # share-price line is restated in the same round as
        # "1 USDC buys N shares" (shares per USDC, the unit a
        # developer thinks in; the old per-million-shares price
        # read 0.000001 USDC at offset 6 and 0.000000 at offset 18).
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        NB = "\u00a0"
        # The formatter: exact multiples compact, anything else
        # keeps its full digits; USDC amounts are never touched.
        self.assertEqual(
            build.compact_shares(f"1,000,000,000,000{NB}shares"),
            "<span class='nowrap'>1T shares</span>")
        self.assertEqual(
            build.compact_shares(
                f"10,000,000,000,000,000{NB}shares"),
            "<span class='nowrap'>10Q shares</span>")
        self.assertEqual(
            build.compact_shares(
                f"1,000,000,000,000,000,000,000,000{NB}shares"),
            "<span class='nowrap'>1×10²⁴ shares</span>")
        self.assertEqual(
            build.compact_shares(f"1,000,000{NB}shares"),
            f"1,000,000{NB}shares")
        self.assertEqual(
            build.compact_shares(
                f"deposit 10,000,000,000{NB}shares == "
                f"10,000,000,001{NB}shares"),
            "deposit <span class='nowrap'>10B shares</span> == "
            f"10,000,000,001{NB}shares")
        self.assertEqual(
            build.compact_shares(f"999,999,999,999{NB}shares"),
            f"999,999,999,999{NB}shares")
        self.assertEqual(
            build.compact_shares(
                f"yield 10,000.000000{NB}USDC, fee 1,000.000000{NB}USDC"),
            f"yield 10,000.000000{NB}USDC, fee 1,000.000000{NB}USDC")
        # The model still emits exact integers; the share-price line
        # is now in buys units on every preset.
        for off, want in ((0, "1,000,000"), (6, "1,000,000,000,000"),
                          (18, "1,000,000,000,000,000,000,000,000")):
            v = Vault(decimals_offset=off,
                      min_deposit=1_000_000 if off else 0,
                      perf_fee_bps=1000 if off else 0)
            price = {r["name"]: r for r in run_all(v)
                     }["share_price_sanity"]["detail"][0]
            self.assertEqual(
                price, f"1{NB}USDC buys {want}{NB}shares (unchanged)")
        # Rendered HTML on all three presets: compact forms in,
        # digit walls and the old price line out. Assertions run on
        # the tag-stripped text: bolding splits the compact forms
        # ("<strong>1</strong>T shares") and nbsp_units wraps the
        # label ("<span class='nowrap'>1 USDC</span> buys").
        for off, mn, fee, compact in (
                (0, 0, 0, "10B shares"),
                (6, 1_000_000, 1000, "1T shares"),
                (18, 1_000_000, 1000, "1×10²⁴ shares")):
            v = Vault(decimals_offset=off, min_deposit=mn,
                      perf_fee_bps=fee)
            html = build.results_html(
                run_all(v), off=off, mn=mn, fee=fee)
            plain = re.sub(r"<[^>]+>", "", html)
            self.assertIn(compact, plain)
            self.assertIn("1 USDC buys", plain)
            self.assertNotIn("price per 1,000,000", plain)
            self.assertNotIn("1,000,000,000,000,000,000,000,000", plain)
            if off == 6:
                self.assertIn("10Q shares", plain)
                self.assertNotIn("10,000,000,000,000,000", plain)
                self.assertNotIn("1,000,000,000,000", plain)
        # The Worker-side template carries the same formatter and
        # the buys splitter branch, and no trace of the old line.
        js = build.checker_results_html_js()
        self.assertIn("function compactShares(s)", js)
        self.assertIn('s.indexOf(" buys ")', js)
        self.assertIn("compactShares(esc(shortValue(row[0],row[1])))",
                      js)
        self.assertIn("compactShares(esc(line))", js)
        self.assertNotIn("price per 1,000,000", js)
        self.assertNotIn("price / 1M shares", js)

    def test_verdict177_shares_abbreviations_explained(self):
        # Visual verdict #177 item 5 (2026-11-24, checker-improvement):
        # #174 compacted share counts ("1T shares", "10Q shares",
        # "1×10²⁴ shares") but the page never said what B/T/Q mean —
        # a first-time reader cannot decode them, and no legend
        # ("trillion", "quadrillion", "10^12") exists anywhere on
        # the page. One muted line under the results grid defines
        # all three suffixes plus the superscript form, and notes
        # the API keeps exact integers. Render-time only: the model
        # strings and the API JSON are untouched.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        legend = ("Share counts are shortened: B = billion (10^9), "
                  "T = trillion (10^12), Q = quadrillion (10^15); "
                  "exact powers of ten above that use the 1×10²⁴ form. "
                  "The API returns exact integers.")
        # CSS: the muted note style exists.
        self.assertIn(
            ".shares-note{font-size:.85em;color:#6b7280;"
            "margin:.7em 0 0}", build.CSS)
        # Python renderer: one legend per run, after the grid closes
        # and before the notice, on passing and failing runs alike.
        for off, mn, fee in ((0, 0, 0), (6, 1_000_000, 1000),
                             (18, 1_000_000, 1000)):
            v = Vault(decimals_offset=off, min_deposit=mn,
                      perf_fee_bps=fee)
            html = build.results_html(
                run_all(v), off=off, mn=mn, fee=fee)
            self.assertEqual(html.count("class='shares-note'"), 1)
            self.assertIn(legend, html)
            last_close = html.rindex("</section>")
            grid_close = html.index("</div>", last_close)
            self.assertLess(grid_close, html.index(legend))
            self.assertLess(html.index(legend),
                            html.index("What to do next"))
        # Worker JS renderer: the same line, between the grid close
        # and the notice append.
        js = build.checker_results_html_js()
        fn = js[js.index("function resultsHTML"):]
        self.assertIn("class='shares-note'", fn)
        self.assertIn(legend, fn)
        self.assertLess(fn.rindex('h+="</div>";'), fn.index(legend))
        self.assertLess(fn.index(legend),
                        fn.index("if(notice){h+=notice;}"))

