    def test_check_detail_numbers_are_bold(self):
        # Visual verdict #94 (second pass), the other half: the
        # detail-box fill went #f9fafb -> #f3f4f6, but labels and
        # figures still share weight and colour — a 16-digit Preview
        # figure fills a whole line without standing out. Figures are
        # now <strong> in both render paths; labels stay regular.
        # Visual verdict #106 item 2: the figures moved into a
        # label/value table, so the invariant moves with them — every
        # numeric token in a value cell is bold, no label cell carries
        # a <strong> at all.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        # Unit helper, composed after nbsp_units: the figure bolds,
        # the unit and the label do not.
        self.assertEqual(
            build.bold_numbers(build.nbsp_units(
                "yield 10,000.000000\u00a0USDC, fee 1,000.000000\u00a0USDC")),
            "yield <span class='nowrap'><strong>10,000.000000</strong> "
            "USDC</span>, fee <span class='nowrap'><strong>1,000.000000"
            "</strong> USDC</span>")
        # Bare counts bold too: the default preset's minimum-viable
        # value ("1 base unit mints 1 share") carries no unit after
        # its figures, so a nowrap-only CSS rule would miss it.
        self.assertEqual(
            build.bold_numbers("1 base unit mints 1 share"),
            "<strong>1</strong> base unit mints <strong>1</strong> share")
        # Both presets, Python path: every figure in every value cell
        # is wrapped, and the count of <strong> matches the count of
        # numeric tokens exactly (no figure left bare); no label cell
        # carries a <strong> (labels stay regular, including the "1"
        # inside the "1 USDC buys" label — bolding
        # is applied to value cells only, never to labels).
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            values = re.findall(r"<td class='check-value'>(.*?)</td>", html)
            self.assertGreater(len(values), 0)
            for inner in values:
                plain = re.sub(r"<[^>]+>", "", inner)
                nums = re.findall(r"-?\d[\d,]*(?:\.\d+)?", plain)
                self.assertEqual(inner.count("<strong>"), len(nums))
                self.assertEqual(inner.count("</strong>"), len(nums))
            labels = re.findall(r"<td class='check-label'>(.*?)</td>", html)
            self.assertGreater(len(labels), 0)
            for inner in labels:
                self.assertNotIn("<strong>", inner)
            sentences = re.findall(
                r"<td class='check-sentence'[^>]*>(.*?)</td>", html)
            # Visual verdict #158: the rounding sentence now renders
            # as a paragraph, not a table cell — same bolding rule.
            sentences += re.findall(
                r"<p class='check-sentence'>(.*?)</p>", html)
            for inner in sentences:
                plain = re.sub(r"<[^>]+>", "", inner)
                nums = re.findall(r"-?\d[\d,]*(?:\.\d+)?", plain)
                # A sentence may carry no figure at all ("floor/ceil
                # directions hold"); the count must still match.
                self.assertEqual(inner.count("<strong>"), len(nums))
                self.assertEqual(inner.count("</strong>"), len(nums))
            # Spot check the long figures read as bold number + plain
            # unit, and a label stays outside any <strong>.
            self.assertIn("<strong>10,000.000000</strong> USDC", html)
            self.assertIn(
                "<td class='check-label'>Yield</td>"
                "<td class='check-value'><span class='nowrap'>"
                "<strong>10,000.000000</strong> USDC</span></td>", html)
            self.assertNotIn("<strong>Yield", html)
            self.assertNotIn("<strong>1 USDC", html)
        # Worker-side template: same helper, same application — bold
        # on the value, plain on the label.
        js = build.checker_results_html_js()
        self.assertIn(
            "function boldNumbers(s){return s.replace("
            "/-?\\d[\\d,]*(?:\\.\\d+)?/g,\"<strong>$&</strong>\");}",
            js)
        self.assertIn("function splitDetailLine(s)", js)
        # Visual verdict #159: the value cell now passes through
        # shortValue first (the "1 base unit mints 1 share" value
        # shortens to "1 base unit") and still through boldNumbers —
        # every numeric token in a value cell stays bold. Visual
        # verdict #174 adds compactShares between them: huge share
        # counts compact ("1T") before bolding, so the bold count
        # still matches the numeric tokens in the displayed text.
        self.assertIn(
            "boldNumbers(nbspUnits(compactShares("
            "esc(shortValue(row[0],row[1])))))", js)
        self.assertIn("nbspUnits(esc(shortLabel(row[0])))", js)
        # The same call survives for the sentence fallback — rounding's
        # "floor/ceil directions hold" now renders as a
        # <p class='check-sentence'>, with the <td> form kept for
        # sentence rows inside mixed tables; the old per-line
        # <p class='check-detail'> loop is gone (pinned in the
        # block-structure test above).
        self.assertIn("boldNumbers(nbspUnits(compactShares(esc(line))))",
                      js)

    def test_donation_table_puts_victim_loss_second(self):
        # Mobile render at 360px (2026-11-18): the donation table is
        # 411px wide inside a 284px scroll wrap, so the third column
        # sits off-screen until the visitor discovers the horizontal
        # swipe — and the third column was Victim loss, the number the
        # verdict turns on (0.909091 USDC on the noprot preset). Victim
        # loss is now the second column in both render paths, so it is
        # in view without scrolling; Attacker net moves third. Numbers
        # and breach marking are unchanged, only the order.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        header = "<th>Donation (USDC)</th><th>Victim loss (USDC)</th>" \
            "<th>Attacker net (USDC)</th><th>Note</th>"
        self.assertIn(header, html)
        # The 1,000,000 USDC row: victim loss 0.909091 first, then
        # attacker net -0.090909, both in that order in the row.
        row = html[html.index("1,000,000</td>"):]
        self.assertLess(row.index("0.909091"), row.index("-0.090909"))
        self.assertIn("<td class='breach'>0.909091</td>", html)
        # The Worker-side template renders the same order.
