    def test_donation_note_column_uses_checkmark_not_repeated_words(self):
        # Visual verdict #103 item 4 (2026-11-18): the donation table's
        # Note column repeated the words "Within pass bound" on every
        # clean row — three times on the default preset, twice on
        # noprot — while the breach rows already said their verdict in
        # words. A clean row now carries one green checkmark (title
        # attribute keeps the words for hover), the breach wording is
        # 'Breaches bound' (#182, was 'Breaches pass bound'), and the
        # legend lives once in the Pass bound paragraph below the
        # table. Both render paths.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        # The words survive only in the checkmark's title attribute
        # (hover text), never as a visible cell.
        self.assertNotIn(">Within pass bound</td>", html)
        self.assertEqual(html.count("title='Within pass bound'"), 2)
        # noprot: two breaching rows keep the words, two clean rows get
        # the checkmark.
        self.assertEqual(html.count("Breaches bound"), 2)
        self.assertEqual(
            html.count("<td class='ok' title='Within pass bound'>\u2713</td>"), 2)
        self.assertIn("\u2713 means within the pass bound; values in red "
                      "breach it.", html)
        # Default preset: all four rows clean, four checkmarks, no
        # breach wording at all.
        html_default = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertNotIn("Breaches bound", html_default)
        self.assertNotIn(">Within pass bound</td>", html_default)
        self.assertEqual(
            html_default.count(
                "<td class='ok' title='Within pass bound'>\u2713</td>"), 4)
        self.assertEqual(html_default.count("title='Within pass bound'"), 4)
        # The Worker-side template renders the same marks: the words
        # appear once, in the checkmark's title attribute.
        js = build.checker_results_html_js()
        self.assertEqual(js.count("Within pass bound"), 1)
        self.assertNotIn('"Within pass bound"', js)
        self.assertIn("Breaches bound", js)
        self.assertNotIn("Breaches pass bound", js)
        self.assertIn("\\u2713", js)
        self.assertIn("class='ok' title='Within pass bound'", js)
        self.assertIn("\\u2713 means within the pass bound; values in "
                      "red breach it.", js)
        self.assertIn(".ok{color:#0a7d2c;font-weight:700}", build.CSS)

    def test_donation_note_column_is_capped(self):
        # Visual verdict #182 (2026-11-24, checker-improvement):
        # the breach Note shortened from "Breaches pass bound" to
        # "Breaches bound" and the cap widened 6.25em to 8.5em so
        # the new label fits on one line. Pixel-measured
        # (hidden_files/measure-verdict182.py and
        # probe-verdict182-lines.py, table font 16.15px): the
        # label is 129.4px = 8.01em IN THE CELL, because .breach
        # is bold — a detached regular-weight probe read only
        # 123.3px, so the first cut at 8em (129.2px) missed by
        # 0.2px and the rows stayed two lines (caught by the
        # pixel re-measure, not by the tests). 8.5em = 137.3px
        # of content leaves ~8px (~6%) of slack for cross-system
        # font variation; the 6.25em cap (100.9px) would still
        # wrap the label to "Breaches" / "bound", so the label
        # change alone does not unify row heights. The breach
        # rows drop from two lines (69px) to one (42px, same as
        # the clean rows); the Note column grows 125px to ~162px
        # on both presets and the three number columns give back
        # ~10px each. At 360px the cap is inert (measured): the
        # table is sized by min-content there, and the longest
        # word is still "Breaches", so the Note column width is
        # unchanged from baseline. The cap lives on the donation
        # table only — the .check-table label/value tables and
        # the guide tables keep their own layout. #179's 6.25em
        # derivation (wrapping "Breaches pass bound" to
        # "Breaches" / "pass bound") is retired with the old
        # wording.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        self.assertIn(".donation-table th:last-child,"
                      ".donation-table td:last-child{width:8.5em}",
                      build.CSS)
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("<table class='donation-table'>", html)
        self.assertEqual(html.count("<table class='donation-table'>"), 1)
        # The breach wording is the new short label in both
        # renderers; the old wording is gone.
        self.assertEqual(html.count("Breaches bound"), 2)
        self.assertNotIn("Breaches pass bound", html)
        js = build.checker_results_html_js()
        self.assertIn("<table class='donation-table'>", js)
        self.assertEqual(js.count("<table class='donation-table'>"), 1)
        self.assertIn("Breaches bound", js)
        self.assertNotIn("Breaches pass bound", js)

    def test_donation_attacker_net_loss_is_muted(self):
        # Visual verdict #106 (noprot item 2), confirmed #107/#108:
        # in the donation table a negative attacker net sat in the
        # same black as the victim loss, so "-999.998101" next to
        # "0.000900" (default preset) or "-999.899111" next to the red
        # "0.099890" (noprot) read as a huge victim loss. A negative
        # attacker net is the attacker's loss — good news, not the
        # number the verdict turns on — so it renders muted grey
        # (.att-loss, the site's secondary #6b7280); a positive
        # attacker net still breaches in red; error rows stay plain.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        # Default preset: all four attacker nets negative, all muted.
        html = build.results_html(
            run_all(Vault(decimals_offset=6, min_deposit=1_000_000,
                          perf_fee_bps=1000)),
            vic=100_000_000_000, off=6, mn=1_000_000, fee=1000)
        self.assertEqual(html.count("class='att-loss'"), 4)
        self.assertIn("<td class='att-loss'>-999.998101</td>", html)
        self.assertIn("<td class='att-loss'>-0.999999</td>", html)
        # The victim-loss cells are untouched: no breach red here.
        self.assertNotIn("<td class='breach'>0.000900</td>", html)
        # noprot: the two breaching victim losses stay red, all four
        # attacker nets (all negative) are muted, not black.
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertEqual(html.count("class='att-loss'"), 4)
        self.assertIn("<td class='att-loss'>-999.899111</td>", html)
        self.assertIn("<td class='att-loss'>-0.090909</td>", html)
        self.assertIn("<td class='breach'>0.909091</td>", html)
        self.assertIn("<td class='breach'>0.099890</td>", html)
        # Synthetic rows: a profiting attacker still breaches red, an
        # error row stays plain "—" (no att-loss, no breach).
        mixed = [{"name": "donation_inflation", "pass": False, "detail": [
            {"donation": 1_000_000_000, "victim_loss": 6,
             "attacker_net": 5000},
            {"donation": 1_000_000_000_000, "victim_loss": 909091,
             "attacker_net": -90909},
            {"donation": 1_000_000_000_000_000, "victim_loss": None,
             "attacker_net": None, "error": "below minimum deposit"}]}]
        html = build.results_html(mixed, vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertIn("<td class='breach'>0.005000</td>", html)
        self.assertIn("<td class='att-loss'>-0.090909</td>", html)
        self.assertIn("<td>—</td>", html)
        self.assertEqual(html.count("class='att-loss'"), 1)
        # The CSS rule and the Worker-side template carry the same
        # class and the same sign condition.
        self.assertIn(".att-loss{color:#6b7280}", build.CSS)
        js = build.checker_results_html_js()
        self.assertIn("class='att-loss'", js)
        self.assertIn("BigInt(row.attacker_net)<0n", js)

    def test_email_params_block_is_light_full_width_box(self):
        # Visual verdict #98 (2026-11-18) supersedes #76/#96: the
        # content-width fix made the block a ~270px narrow dark slab
        # (21% of the card) under a full-width dark curl example — it
        # reads as an unfinished half-block. Both dark shapes are
        # wrong (full-width dark leaves ~960px empty dark space to the
        # right; narrow dark looks broken), so the block is no longer
        # a dark code block: full-width light box in the page's #f9fafb
        # form language, thin border. The API curl block keeps the
        # dark full-width code style — its one long line fills it, so
        # the rule is scoped to .email-para.
        # Follow-up from visual verdict #100 (2026-11-18, minor
        # observation): #f9fafb on the white main card is ~1.02:1
        # contrast, so the box was invisible and the block read as
        # plain text with no code-box background. The fill is now
        # the site's established detail gray #f3f4f6 (same as
        # .check-detail) with the deeper #d1d5db border — still
        # light, still full-width, but visibly a box.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        self.assertIn(
            ".email-para pre{background:#f3f4f6;color:#111827;"
            "border:1px solid #d1d5db}",
            build.CSS)
        self.assertNotIn(".email-para pre{background:#f9fafb", build.CSS)
        self.assertNotIn(".email-para pre{width:max-content", build.CSS)
        # The global dark pre style still exists for the curl block.
        self.assertIn("pre{background:#111827;color:#e5e7eb", build.CSS)
        # Both render paths carry the same .email-para block, so the
        # one CSS rule covers the static page and the Worker re-render.
        html = build.checker_body()
        self.assertIn('<div class="email-para">', html)
        self.assertIn('<pre class="api-example"><code id="email-params">', html)
        worker = build.worker_js(
            dict((p, b) for p, t, d, k, b in build.PAGES))
        self.assertIn("email-para", worker)
        self.assertIn(".email-para pre{background:#f3f4f6;color:#111827;"
                      "border:1px solid #d1d5db}",
                      worker)
        self.assertNotIn(".email-para pre{background:#f9fafb", worker)
        # The blanket "width:max-content" guard used to live here, but
        # it trips on any unrelated rule that legitimately uses it.
        # (Visual verdict #115 (d) once capped the /audit/ toggle
        # button with max-width:max-content; verdict #116 replaced
        # that with a full-width wrapper span, so no such rule remains
        # on the toggle.) The guard is scoped to the rule it protects
        # instead — the .email-para pre must never be content-width
        # (verdict #98: that made it a ~270px narrow slab).
        self.assertNotIn(".email-para pre{width:max-content", worker)
        # The curl example is a plain <pre> outside .email-para and
        # keeps the dark full-width code style.
        self.assertIn('<pre class="api-example"><code id="api-curl">', html)

