        for script in (build.COPY_LINK_SCRIPT,
                       (Path.home() / "workspace/taskmarket/site/build.py"
                        ).read_text().split('h+="<script>')[1].split("</script>")[0]):
            self.assertIn("function copyResultsLink(btn)", script)
