    def test_guide_link_is_named_and_at_card_bottom(self):
        # Visual verdict #54 item c (2026-11-17): "Read the guide
        # &rarr;" appeared six times, word for word, between each
        # card's description and its result numbers — six identical
        # green links that interrupted the desc-to-numbers flow and
        # read as noise. The link now sits at the bottom of each
        # card, after the numbers, muted grey and small, and names
        # its check ("Guide: Donation inflation &rarr;") so the six
        # links are no longer identical. The JS renderer mirrors
        # this (verified by the /tmp node harness, not this suite).
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html = build.results_html(
            run_all(Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0)),
            vic=100_000_000_000, off=0, mn=0, fee=0)
        self.assertNotIn("Read the guide", html)
        expected = [
            ("Rounding directions", "/guides/erc4626-rounding-errors/"),
            ("Donation inflation", "/guides/erc4626-donation-attack/"),
            ("Preview consistency", "/guides/erc4626-preview-consistency/"),
            ("Fee conservation", "/guides/erc4626-fee-conservation/"),
            ("Share-price sanity", "/guides/vault-share-price-manipulation/"),
            ("Minimum viable deposit", "/guides/erc4626-minimum-deposit/"),
        ]
        self.assertEqual(html.count("class='check-guide'"), 6)
        cards = html.split("<section class='check-card")[1:]
        self.assertEqual(len(cards), 6)
        # Card order follows run_all(), not CHECK_META — match by title.
        # Each chunk runs to the next card's opening tag, so cut it at
        # its own closing tag first (the last card has no next card —
        # its chunk runs on into the notice div).
        by_title = {}
        for card in cards:
            card = card.split("</section>", 1)[0]
            title = card.split("</span> ", 1)[1].split("</h3>", 1)[0]
            by_title[title] = card
        self.assertEqual(sorted(by_title),
                         sorted(title for title, _ in expected))
        for title, href in expected:
            card = by_title[title]
            self.assertIn(f"<p class='check-guide'><a href='{href}'>"
                          f"Guide: {title} &rarr;</a></p>", card)
            # The guide link is the card's last paragraph: it comes
            # after the description and after every result number.
            self.assertTrue(card.rstrip().endswith(
                f"<p class='check-guide'><a href='{href}'>"
                f"Guide: {title} &rarr;</a></p>"))
        src = (Path.home() / "workspace/taskmarket/site/build.py"
               ).read_text()
        self.assertIn(".check-guide{font-size:.85em;color:#6b7280", src)
        self.assertIn(".check-guide a{color:#6b7280", src)
        self.assertNotIn("Read the guide", src)

    def test_results_cards_two_column_grid(self):
        # Visual verdict #152 (2026-11-22, checker-improvement):
        # the six cards stacked in one ~1020px column took ~3 screens
        # to read at 1920px. At desktop width they form a two-column
        # grid; the donation card (table + chart) spans both columns.
        # Below 1024px the single column stays. Structure, not
        # appearance, is what this test can pin: the grid wrapper,
        # the wide class on exactly the donation and rounding cards,
        # and the CSS rule that turns the wrapper into a grid at
        # desktop width.
        # Visual verdict #154 (2026-11-22, checker-improvement):
        # one wide card left five halves that can never pair — on
        # the ALL PASS page Rounding sat alone in row 1. Rounding
        # spans both columns too now (two wides + four halves tile
        # exactly), and the grid is dense so a failing half card
        # landing before a wide card backfills instead of stranding.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            self.assertEqual(html.count('<div class="check-grid">'), 1)
            self.assertEqual(html.count("<section class='check-card"), 6)
            self.assertEqual(
                html.count("<section class='check-card check-card--wide'>"),
                2)
            wide_titles = [
                s.split("</h3>", 1)[0].split("</span> ", 1)[1]
                for s in html.split(
                    "<section class='check-card check-card--wide'>")[1:]]
            self.assertEqual(sorted(wide_titles),
                             ["Donation inflation", "Rounding directions"])
            # The grid opens before the first card and closes after
            # the last one, with nothing but a newline between the
            # last card's close and the grid close.
            self.assertLess(html.index('<div class="check-grid">'),
                            html.index("<section class='check-card"))
            last_close = html.rindex("</section>")
            grid_close = html.index("</div>", last_close)
            self.assertEqual(
                html[last_close + len("</section>"):grid_close].strip(),
                "")
        self.assertIn(
            "@media (min-width:1024px){.check-grid{display:grid;"
            "align-items:start;grid-auto-flow:dense;"
            "grid-template-columns:1fr 1fr;gap:1em;margin:1em 0}"
            ".check-grid .check-card{margin:0;display:flex;"
            "flex-direction:column}"
            ".check-card--wide{grid-column:1/-1}}",
            build.CSS)
        # Visual verdict #162 (2026-11-23): the notice no longer
        # sits inside the grid, so the .check-grid .notice rule
        # that spanned it full-width is gone with it.

