    def test_check_grid_never_orphans_a_card(self):
        # Visual verdict #154 (2026-11-22, checker-improvement):
        # the orphan was not a one-page accident. The failing-first
        # sort reorders the cards, so the grid order depends on
        # which checks fail — and the model reaches four failing
        # sets (swept 2026-11-22: offsets 0/3/6/18/30 x fees
        # 0/1000/10000 x mins 0/1/1000 USDC x victims 1k/100k x
        # three vault states): none, {donation}, {donation, min},
        # {min} alone. Two wides + four halves tile exactly only
        # with dense backfill: in {min} the failing half card lands
        # before both wide cards, and in {donation, min} between
        # them — without dense each shows two lone half cards.
        # This test simulates CSS grid auto-placement (dense, two
        # columns) on the real rendered order for every reachable
        # set and requires every row full: one wide card, or two
        # half cards. The Worker JS renderer must carry the same
        # wide condition; its live rendering is pinned by the
        # rounding-wide node harness, not by this suite.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build

        def place(cards):
            # cards: True = wide (spans both columns), False = half.
            # Dense auto-placement: a half takes the earliest free
            # cell; a wide takes the first row with both cells free
            # (always a fresh row here — a live row never has two
            # free cells, halves fill left to right).
            rows = []
            for wide in cards:
                if wide:
                    rows.append(["wide", "wide"])
                else:
                    for row in rows:
                        if row[0] is None:
                            row[0] = "half"
                            break
                        if row[1] is None:
                            row[1] = "half"
                            break
                    else:
                        rows.append(["half", None])
            return rows

        cases = (
            # ALL PASS.
            (Vault(decimals_offset=6, min_deposit=1_000_000,
                   perf_fee_bps=1000), {}),
            # Donation fails alone.
            (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
             {"off": 0, "mn": 0, "fee": 0}),
            # Minimum-viable-deposit fails alone (min 1000 USDC).
            (Vault(decimals_offset=6, min_deposit=1_000_000_000,
                   perf_fee_bps=1000),
             {"off": 6, "mn": 1_000_000_000, "fee": 1000}),
            # Donation + minimum-viable-deposit fail together.
            (Vault(decimals_offset=0, min_deposit=10**15, perf_fee_bps=0),
             {"off": 0, "mn": 10**15, "fee": 0}),
        )
        for v, kwargs in cases:
            html = build.results_html(run_all(v), **kwargs)
            cards = [s.startswith(" check-card--wide'>")
                     for s in html.split("<section class='check-card")[1:]]
            self.assertEqual(len(cards), 6)
            self.assertEqual(sum(cards), 2)
            for row in place(cards):
                self.assertIn(row, (["wide", "wide"], ["half", "half"]),
                              f"orphaned row {row} in {cards}")
        js = build.checker_results_html_js()
        self.assertIn(
            "(r.name===\"donation_inflation\"||r.name===\"rounding\")"
            "?\" check-card--wide\":\"\"",
            js)

    def test_short_cards_state_their_pass_rule(self):
        # Visual verdict #104 item 1 (corrected): the short cards
        # carry one detail line against the donation card's table +
        # chart, so the page reads as one long card and four sparse
        # ones. Equal heights would manufacture real blank space
        # inside the cards (#103), so the short cards instead state
        # their pass rule — the exact criterion and the scenario it
        # was tested on, straight from the model. Donation already
        # has its pass-bound paragraph and minimum-viable-deposit
        # states its rule in its blurb, so those two carry no rule
        # line. The rule texts below are verified against the model
        # docstrings and the amounts the checks actually run:
        # rounding amounts (1, 100, 10,000 USDC) and the 1-base-unit
        # tolerance; preview 10,000 USDC deposit + 1,000,000-share
        # mint/redeem; fee 10,000 USDC yield; share-price two
        # 100,000 USDC deposits, 1-base-unit tolerance.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        expected = {
            "Rounding directions":
                "Every preview within 1 base unit of the exact ratio"
                " — deposits of 1, 100, 10,000 USDC.",
            "Preview consistency":
                "Preview must equal execution exactly — tested on a "
                "10,000 USDC deposit and a 1,000,000-share mint and redeem.",
            "Fee conservation":
                "Holder gain + fee must equal the 10,000 USDC yield "
                "exactly, and the fee must equal the yield times the "
                "fee rate.",
            "Share-price sanity":
                "1 USDC must buy the same number of shares after a "
                "second 100,000 USDC deposit (price checked to within "
                "1 base unit).",
        }
        for v, kwargs in (
                (Vault(decimals_offset=6, min_deposit=1_000_000,
                       perf_fee_bps=1000), {}),
                (Vault(decimals_offset=0, min_deposit=0, perf_fee_bps=0),
                 {"off": 0, "mn": 0, "fee": 0})):
            html = build.results_html(run_all(v), **kwargs)
            self.assertEqual(html.count("<p class='check-rule'>"), 4)
            cards = html.split("<section class='check-card")[1:]
            by_title = {}
            for card in cards:
                card = card.split("</section>", 1)[0]
                title = card.split("</span> ", 1)[1].split("</h3>", 1)[0]
                by_title[title] = card
            for title, rule in expected.items():
                self.assertIn(
                    f"<p class='check-rule'><strong>Pass rule:</strong> "
                    f"{rule}</p>", by_title[title])
                # The rule sits after the numbers and before the guide
                # link, which stays the card's last paragraph.
                self.assertLess(
                    by_title[title].index("check-rule"),
                    by_title[title].index("check-guide"))
            for title in ("Donation inflation",
                          "Minimum viable deposit"):
                self.assertNotIn("check-rule", by_title[title])
        self.assertIn(".check-rule{font-size:.92em;color:#4b5563",
                      build.CSS)
        # The Worker-side template renders the same lines: the rule
        # is the fourth CHECK_META element, rendered after the
        # details block and before the guide link.
        js = build.checker_results_html_js()
        self.assertIn("if(m[3]) h+=\"<p class='check-rule'>", js)
        for rule in expected.values():
            self.assertIn(rule, js)

    def test_cli_seeded_vault_passes_where_new_vault_fails(self):
        # The hosted checker lets a user seed the vault state (assets +
        # shares already in it); the repo CLI could not, so a live 50M
        # USDC vault at offset 0 could not be reproduced from the repo.
        # Verified against the model: a new vault at offset 0 fails
        # the donation check (worst victim loss 0.909091 USDC); the
        # same vault seeded with 50M USDC at price 1.00 passes all
        # six (worst victim loss 0.000013 USDC).
        import io
        from contextlib import redirect_stdout
        from pathlib import Path
        import sys
        sys.path.insert(0, str(Path(__file__).parent))
        from check_vault import main as cli_main
        with redirect_stdout(io.StringIO()):
            self.assertEqual(cli_main(["--offset", "0"]), 1)
        out = io.StringIO()
