    def test_hero_flow_arrow_is_a_slim_chevron(self):
        # Visual verdict #100 (2026-11-18): the homepage hero's flow
        # arrows were two chunky white blocks - a 6px bar plus a 24px
        # triangle - that read as clip-art against the dark-green hero.
        # They are now a slim chevron: a connector, not a block.
        # Pins the new geometry and forbids the old one.
        # Visual verdict #101 (2026-11-18) then called the 2px /
        # 60%-white chevron thin and low-contrast: 3px strokes in
        # 90%-white now.
        # Visual verdict #123 (2026-11-20) still read the 32x16 /
        # 3px / 90%-white chevron as a small grey ">" at 1919px:
        # enlarged to 40x20, 4px strokes, solid white.
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        self.assertIn(
            ".flow-arrow{position:relative;align-self:center;"
            "flex:0 0 auto;width:40px;height:20px}",
            build.CSS)
        self.assertIn(
            ".flow-arrow::before{content:\"\";position:absolute;left:0;"
            "top:8px;width:39px;height:4px;"
            "background:#fff}",
            build.CSS)
        self.assertIn(
            ".flow-arrow::after{content:\"\";position:absolute;right:5px;"
            "top:4px;width:12px;height:12px;"
            "border-top:4px solid #fff;"
            "border-right:4px solid #fff;"
            "transform:rotate(45deg)}",
            build.CSS)
        self.assertNotIn("width:48px;height:24px", build.CSS)
        self.assertNotIn("border-width:12px 0 12px 16px", build.CSS)
        # Connectivity invariant: the 12x12 chevron head sits
        # right:5px, so its box spans x=23..35 with centre (29, 10);
        # rotate(45deg) puts its vertex at x = 29 + 6*sqrt(2) = 37.49.
        # The 39px shaft ends past the vertex, so shaft and head
        # overlap by ~1.5px and render as one arrow.
        import math
        shaft_end = 39
        chevron_vertex_x = (40 - 5 - 12 + 6) + 6 * math.sqrt(2)
        self.assertGreater(shaft_end, chevron_vertex_x)
        worker = build.worker_js(
            dict((p, b) for p, t, d, k, b in build.PAGES))
        self.assertIn(".flow-arrow{position:relative;align-self:center;"
                      "flex:0 0 auto;width:40px;height:20px}", worker)

    def test_no_built_page_contains_undefined(self):
        # Sitemap sweep 2026-11-20 (hidden_files/sitemap-sweep.mjs):
        # all 238 sitemap URLs returned 200 with no "{{" leak, but
        # exactly one page contained the literal word "undefined" --
        # the deposit-into-queue guide, where it was legitimate prose
        # ("the payable date is not late, it is undefined"). In a
        # guide full of exact numbers it reads like a rendering bug,
        # so the sentence was rewritten ("there is no payable date").
        # This test rebuilds from build.py and pins the site-wide
        # invariant: no built page may contain "undefined" anywhere,
        # so any future occurrence -- prose or template leak -- fails
        # loudly. (The legitimate code uses -- typeof process !==
        # "undefined", passing undefined for a defaulted parameter,
        # the usdc() null guard -- live in the Worker script, not in
        # any page's HTML, so they cannot trip this.)
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        build.main()
        site = Path.home() / "workspace/taskmarket/site"
        bad = sorted(str(p.relative_to(site)) for p in site.rglob("*.html")
                     if "undefined" in p.read_text())
        self.assertEqual(bad, [])

    def test_meta_descriptions_within_limits(self):
        # 2026-11-20: the /guides/ index carried a 5,536-char meta
        # description -- the whole guides index pasted into the
        # description field, one topic appended per new guide until it
        # became a keyword dump. It shipped verbatim into <meta
        # name="description">, og:description, twitter:description and
        # the JSON-LD TechArticle description; search engines truncate
        # at ~160 chars, so the page showed as a truncated keyword
        # list. Replaced with a 158-char summary. This test rebuilds
        # from build.py and pins the invariant: no built page's meta
        # description may exceed 1000 chars (the longest legitimate
        # article summary today is 775), and the /guides/ index --
        # the one page whose description is a summary, not an article
        # abstract -- stays within 200.
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        build.main()
        site = Path.home() / "workspace/taskmarket/site"
        pat = re.compile(r'<meta name="description" content="([^"]*)">')
        too_long = []
        for p in sorted(site.rglob("*.html")):
            m = pat.search(p.read_text())
            if m and len(m.group(1)) > 1000:
                too_long.append((str(p.relative_to(site)), len(m.group(1))))
        self.assertEqual(too_long, [])
        guides = (site / "guides/index.html").read_text()
        gm = pat.search(guides)
        self.assertIsNotNone(gm)
        self.assertLessEqual(len(gm.group(1)), 200)
        self.assertIn("Plain-English guides to ERC-4626 vault accounting",
                      gm.group(1))

    def test_sitemap_lastmod_keeps_date_for_unchanged_pages(self):
        # 2026-11-20: the sitemap stamped every page with the build date,
        # so all 238 URLs claimed to have changed on every deploy. Now a
        # page's date advances only when its content changes. This pins
        # both directions with a seeded state file: an unchanged page
        # keeps its old date, a changed page moves to today, and a new
        # page starts at today. The hash strips the shared <style> and
        # <script> blocks, so a one-line CSS tweak does not stamp the
        # whole site as changed.
        import json
        import sys
        import tempfile
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        html_a = "<html><head><title>A</title></head><body><main><p>alpha</p></main></body></html>"
        html_b = "<html><head><title>B</title></head><body><main><p>beta</p></main></body></html>"
        html_b2 = "<html><head><title>B</title></head><body><main><p>beta changed</p></main></body></html>"
        with tempfile.TemporaryDirectory() as d:
            state = Path(d) / "state.json"
            seeded = {"/a/": {"hash": build._content_hash(html_a),
                              "lastmod": "2026-11-01"},
                      "/b/": {"hash": build._content_hash(html_b),
                              "lastmod": "2026-11-02"}}
            state.write_text(json.dumps(seeded))
            lm = build.page_lastmods({"/a/": html_a, "/b/": html_b},
                                     state_file=state)
            self.assertEqual(lm["/a/"], "2026-11-01")
            self.assertEqual(lm["/b/"], "2026-11-02")
            build.save_lastmod_state({"/a/": html_a, "/b/": html_b}, lm,
                                     state_file=state)
            # Only B's content changes: only B's date advances.
            lm2 = build.page_lastmods({"/a/": html_a, "/b/": html_b2},
                                      state_file=state)
            self.assertEqual(lm2["/a/"], "2026-11-01")
            self.assertEqual(lm2["/b/"], build.BUILD_DATE)
            build.save_lastmod_state({"/a/": html_a, "/b/": html_b2}, lm2,
                                     state_file=state)
            # A brand-new page starts at today.
            lm3 = build.page_lastmods({"/a/": html_a, "/b/": html_b2,
                                       "/c/": html_a},
                                      state_file=state)
            self.assertEqual(lm3["/c/"], build.BUILD_DATE)
            # A shared CSS change alone must not move any page: the
            # <style> block is stripped before hashing.
            css_a = html_a.replace("</head>", "<style>p{color:red}</style></head>")
            css_b = html_a.replace("</head>", "<style>p{color:blue}</style></head>")
            lm4 = build.page_lastmods({"/a/": css_a}, state_file=state)
            lm5 = build.page_lastmods({"/a/": css_b}, state_file=state)
            self.assertEqual(lm4["/a/"], lm5["/a/"])

    def test_preset_option_labels_fit_a_360px_select(self):
        # 2026-11-20: mobile verdict (rendered 360px screenshots):
        # every preset option label was cut off mid-word inside the
        # <select> ("AlphaPrimer — offset 6, min 1 U…"), because the
        # labels carried the min/fee numbers (up to 58 chars) while a
        # 360px select shows ~35. The numbers live in the fields
        # directly below and in the Parameters line, so the labels now
        # carry only the preset name + offset. Both render paths
        # (static checker_body and the Worker-side formHTML) must
        # carry the same four short labels, and no long label may
        # survive in either. ("no minimum, no fee" still appears in
        # guide prose -- scope the absence checks to the option lists.)
        import re
        import sys
        from pathlib import Path
        sys.path.insert(0, str(Path.home() / "workspace/taskmarket/site"))
        import build
        labels = ("AlphaPrimer — offset 6",
                  "No protection — offset 0",
                  "Minimum + fee, no offset",
                  "Offset 18")
        html = build.checker_body()
        form = html[html.index('<form id="checker-form"'):
                    html.index("</form>")]
        for label in labels:
            self.assertIn(f">{label}</option>", form)
        self.assertNotIn("min 1 USDC, fee 10%", form)
        self.assertNotIn("no minimum, no fee", form)
        worker = build.worker_js(
            dict((p, b) for p, t, d, k, b in build.PAGES))
        opts = re.search(r"const opts = \[(.*?)\];", worker, re.S).group(1)
        for label in labels:
            self.assertIn(f'"{label}"', opts)
        self.assertNotIn("min 1 USDC, fee 10%", opts)
        self.assertNotIn("no minimum, no fee", opts)
        # Belt and braces: no option label in either path may exceed
        # 28 chars -- the 360px select shows ~35, so 28 leaves room
        # for wider real-browser fonts and the chevron.
        for m in re.finditer(r"<option[^>]*>([^<]*)</option>", form):
            self.assertLessEqual(len(m.group(1)), 28, m.group(1))
        for m in re.finditer(r'"([^"]*)"\]', opts):
            self.assertLessEqual(len(m.group(1)), 28, m.group(1))

